package com.fauxbingo;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup("fauxbingo")
public interface FauxBingoConfig extends Config
{
	@ConfigSection(
		name = "API",
		description = "Enable external API support",
		position = 0
	)
	String apiSection = "api";

	@ConfigSection(
		name = "Team Overlay",
		description = "Configure team name and timestamp overlay display",
		position = 1
	)
	String overlaySection = "overlay";

	@ConfigSection(
		name = "Screenshots",
		description = "Privacy options for evidence screenshots sent to the API",
		position = 2
	)
	String screenshotsSection = "screenshots";

	@ConfigSection(
		name = "Advanced",
		description = "Developer/advanced settings. Most users should never need these.",
		position = 3,
		closedByDefault = true
	)
	String advancedSection = "advanced";

	// ========== API Configuration ==========

	@ConfigItem(
			keyName = "enableBingoApi",
			name = "Enable Bingo API",
			description = "Enables the bingo API for team lookup, presence heartbeat, and reporting drops/deaths.",
			warning = "This feature will submit your character name, account info, and drop/death data to a 3rd-party server not controlled or verified by Runelite developers.",
			position = 1,
			section = apiSection
	)
	default boolean enableBingoApi()
	{
		return false;
	}

	@ConfigItem(
			keyName = "apiToken",
			name = "API Token",
			description = "Your player token from the bingo website, sent to authenticate with the API.",
			position = 2,
			section = apiSection
	)
	default String apiToken()
	{
		return "";
	}

	@ConfigItem(
			keyName = "enableWomAutoUpdate",
			name = "Enable WOM Auto-Update",
			description = "Automatically update your WiseOldMan stats on logout or when gaining 10k+ XP",
			position = 3,
			section = apiSection
	)
	default boolean enableWomAutoUpdate()
	{
		return false;
	}

	@ConfigItem(
			keyName = "showTeamIconsInChat",
			name = "Show Team Icons in Chat",
			description = "Displays a team icon before player names in chat for active bingo event participants, and renders team shortcodes such as :fork: as that team's icon. Requires Bingo API to be enabled.",
			position = 4,
			section = apiSection
	)
	default boolean showTeamIconsInChat()
	{
		return false;
	}


	// ========== Team Overlay Configuration ==========

	@ConfigItem(
		keyName = "displayOverlay",
		name = "Display Overlay",
		description = "Displays the team name and timestamp overlay on your game screen",
		position = 1,
		section = overlaySection
	)
	default boolean displayOverlay()
	{
		return false;
	}

	@ConfigItem(
		keyName = "displayDateTime",
		name = "Date & Time",
		description = "Adds the date and time to the overlay",
		position = 2,
		section = overlaySection
	)
	default boolean displayDateTime()
	{
		return true;
	}

	@ConfigItem(
		keyName = "teamName",
		name = "Team Name",
		description = "Your team name to display in the overlay",
		position = 3,
		section = overlaySection
	)
	default String teamName()
	{
		return "";
	}

	@ConfigItem(
		keyName = "teamNameColor",
		name = "Team Name Color",
		description = "The color of the team name in the overlay",
		position = 4,
		section = overlaySection
	)
	default Color teamNameColor()
	{
		return Color.GREEN;
	}

	@ConfigItem(
		keyName = "dateTimeColor",
		name = "Date & Time Color",
		description = "The color of the date and time in the overlay",
		position = 5,
		section = overlaySection
	)
	default Color dateTimeColor()
	{
		return Color.WHITE;
	}

	// ========== Screenshots Configuration ==========

	@ConfigItem(
		keyName = "screenshotHidePrivateMessages",
		name = "Hide PMs in Screenshots",
		description = "Hide private message windows before taking evidence screenshots for the API, then restore them",
		position = 1,
		section = screenshotsSection
	)
	default boolean screenshotHidePrivateMessages()
	{
		return false;
	}

	@ConfigItem(
		keyName = "screenshotHideChat",
		name = "Hide Chat in Screenshots",
		description = "Hide the main chat area before taking evidence screenshots for the API, then restore it",
		position = 2,
		section = screenshotsSection
	)
	default boolean screenshotHideChat()
	{
		return false;
	}

	// ========== Advanced Configuration ==========

	@ConfigItem(
			keyName = "apiBaseUrl",
			name = "API Base URL",
			description = "Base URL for the bingo API. Only change this for local testing against a dev server; leave default for normal use.",
			position = 1,
			section = advancedSection
	)
	default String apiBaseUrl()
	{
		return "https://fauxbingo.com";
	}
}

package com.fauxbingo;

import com.fauxbingo.handlers.CollectionLogHandler;
import com.fauxbingo.handlers.DeathHandler;
import com.fauxbingo.handlers.LootEventHandler;
import com.fauxbingo.handlers.PetChatHandler;
import com.fauxbingo.handlers.RaidLootHandler;
import com.fauxbingo.handlers.ValuableDropHandler;
import com.fauxbingo.overlay.TeamOverlay;
import com.fauxbingo.services.ApiConfigSanitizer;
import com.fauxbingo.services.DropCorrelationService;
import com.fauxbingo.services.EventEnvelopeSink;
import com.fauxbingo.services.EventsApiService;
import com.fauxbingo.services.InteractionTrackingService;
import com.fauxbingo.services.MeService;
import com.fauxbingo.services.PresenceService;
import com.fauxbingo.services.TeamIconService;
import com.fauxbingo.trackers.XpTracker;
import com.google.inject.Provides;
import java.util.Arrays;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Named;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.UsernameChanged;
import net.runelite.api.events.WorldChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "Faux Bingo",
	description = "Helper plugin for Bingo events ran in the Faux Clan/Community",
	tags = {"faux", "bingo"}
)
public class FauxBingoPlugin extends Plugin
{
	/** Guice binding name for the bingo API base URL. */
	public static final String API_BASE_URL_KEY = "fauxBingoApiBaseUrl";

	/** Fallback for the v1 bingo API (me, teams, seen, events) if the config value is ever blank. */
	private static final String DEFAULT_BINGO_API_BASE_URL = "https://fauxbingo.com";

	private static final String LOOT_TRACKER_PLUGIN_NAME = "Loot Tracker";

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private FauxBingoConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private TeamOverlay teamOverlay;

	@Inject
	private PluginManager pluginManager;

	@Inject
	private EventBus eventBus;

	@Inject
	private MeService meService;

	@Inject
	private PresenceService presenceService;

	@Inject
	private EventsApiService eventsApiService;

	@Inject
	private InteractionTrackingService interactionTrackingService;

	@Inject
	private DropCorrelationService dropCorrelationService;

	@Inject
	private LootEventHandler lootEventHandler;

	@Inject
	private PetChatHandler petChatHandler;

	@Inject
	private CollectionLogHandler collectionLogHandler;

	@Inject
	private ValuableDropHandler valuableDropHandler;

	@Inject
	private RaidLootHandler raidLootHandler;

	@Inject
	private DeathHandler deathHandler;

	@Inject
	private TeamIconService teamIconService;

	@Inject
	private XpTracker xpTracker;

	private volatile boolean loginTriggered = false;
	private String lastRejectedBaseUrl = null;

	@Override
	protected void startUp() throws Exception
	{
		log.info("Faux Bingo started!");

		meService.start();
		presenceService.start();
		eventsApiService.start();
		teamIconService.start();
		dropCorrelationService.start();

		for (Object subscriber : eventSubscribers())
		{
			eventBus.register(subscriber);
		}

		overlayManager.add(teamOverlay);

		warnIfLootTrackerDisabled();

		// Check if already logged in
		checkLogin();
	}

	@Override
	protected void shutDown() throws Exception
	{
		log.info("Faux Bingo stopped!");

		for (Object subscriber : eventSubscribers())
		{
			eventBus.unregister(subscriber);
		}

		overlayManager.remove(teamOverlay);

		meService.shutdown();
		presenceService.shutdown();
		eventsApiService.shutdown();
		teamIconService.shutdown();
		dropCorrelationService.shutdown();
		xpTracker.reset();

		resetState();
	}

	/**
	 * Objects carrying their own {@code @Subscribe} methods. Registered in startUp, unregistered in
	 * shutDown. Built on demand so both paths cannot drift apart.
	 */
	private List<Object> eventSubscribers()
	{
		return Arrays.asList(
			lootEventHandler,
			petChatHandler,
			collectionLogHandler,
			valuableDropHandler,
			raidLootHandler,
			deathHandler,
			interactionTrackingService,
			teamIconService);
	}

	@Subscribe
	public void onUsernameChanged(UsernameChanged event)
	{
		resetState();
		checkLogin();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!event.getGroup().equals("fauxbingo"))
		{
			return;
		}

		String key = event.getKey();
		if (config.enableBingoApi() && (key.equals("enableBingoApi") || key.equals("apiToken") || key.equals("apiBaseUrl")))
		{
			loginTriggered = false;
			checkLogin();
			meService.start();
			presenceService.start();
			eventsApiService.start();
			teamIconService.start();
			clientThread.invoke(() -> {
				Player local = client.getLocalPlayer();
				if (local != null && local.getName() != null && !local.getName().isEmpty())
				{
					meService.refresh(local.getName());
				}
			});
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.LOGGING_IN)
		{
			meService.onLogout();
			resetState();
		}

		if (event.getGameState() == GameState.LOGGED_IN)
		{
			checkLogin();
		}

		xpTracker.onGameStateChanged(event);
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		xpTracker.onStatChanged(event);
	}

	@Subscribe
	public void onWorldChanged(WorldChanged event)
	{
		eventsApiService.onWorldChanged();
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		checkLogin();
		xpTracker.onGameTick();
	}

	private void resetState()
	{
		loginTriggered = false;
		collectionLogHandler.resetState();
		raidLootHandler.resetState();
		eventsApiService.resetSession();
	}

	private void warnIfLootTrackerDisabled()
	{
		try
		{
			for (Plugin plugin : pluginManager.getPlugins())
			{
				if (!LOOT_TRACKER_PLUGIN_NAME.equals(plugin.getName()))
				{
					continue;
				}

				if (!pluginManager.isPluginEnabled(plugin))
				{
					log.warn("Loot Tracker is disabled. Loot from Tempoross, Wintertodt, clue caskets, "
						+ "chests and other non-combat sources will not be reported.");
				}
				return;
			}

			log.warn("Loot Tracker not found. Non-combat loot will not be reported.");
		}
		catch (Exception e)
		{
			log.debug("Could not determine Loot Tracker state", e);
		}
	}

	/** Reads client state, so it has to run on the client thread. */
	private void checkLogin()
	{
		clientThread.invoke(() -> {
			if (loginTriggered || client.getGameState() != GameState.LOGGED_IN)
			{
				return;
			}

			Player local = client.getLocalPlayer();
			if (local != null)
			{
				String name = local.getName();
				if (name != null && !name.isEmpty())
				{
					meService.onLogin(name);
					presenceService.onLogin(name);
					eventsApiService.onLogin(name);
					loginTriggered = true;
				}
			}
		});
	}

	@Provides
	FauxBingoConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(FauxBingoConfig.class);
	}

	/**
	 * Injected as a Provider so it re-resolves per request. RuneLite builds the plugin injector
	 * once per client session and does not rebuild it on enable/disable, so a captured String
	 * would never pick up a config change.
	 */
	@Provides
	@Named(API_BASE_URL_KEY)
	String provideApiBaseUrl(FauxBingoConfig config)
	{
		String configured = config.apiBaseUrl();
		if (ApiConfigSanitizer.sanitize(configured).isEmpty())
		{
			return DEFAULT_BINGO_API_BASE_URL;
		}

		// Not falling back to the default when the URL is unusable
		String normalized = ApiConfigSanitizer.normalizeBaseUrl(configured);
		if (normalized.isEmpty() && !configured.equals(lastRejectedBaseUrl))
		{
			lastRejectedBaseUrl = configured;
			log.warn("API Base URL \"{}\" is not a usable http(s) URL, so the bingo API is disabled. "
				+ "It needs the scheme, e.g. https://example.com", configured);
		}
		return normalized;
	}

	@Provides
	EventEnvelopeSink provideEventEnvelopeSink(EventsApiService sink)
	{
		return sink;
	}
}

package com.fauxbingo.handlers;

import com.fauxbingo.services.DropCorrelationService;
import com.fauxbingo.services.ScreenshotService;
import com.fauxbingo.services.data.DetectionMethod;
import com.fauxbingo.services.data.DropItem;
import com.fauxbingo.services.data.DropSignal;
import java.util.Collections;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.ScriptID;
import net.runelite.api.VarClientStr;
import net.runelite.api.Varbits;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

/**
 * Handles collection log events. Detects new collection log items through both chat messages and
 * notification scripts, and reports them to DropCorrelationService. This is also the only signal
 * that ever learns a pet's real name (see PetChatHandler), and the only signal that can enrich a
 * raid/NPC LOOT signal with achievement confirmation for the same item.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class CollectionLogHandler
{
	private static final String COLLECTION_LOG_TEXT = "New item added to your collection log: ";

	private final Client client;
	private final ScreenshotService screenshotService;
	private final ScheduledExecutorService executor;
	private final DropCorrelationService dropCorrelationService;

	private boolean notificationStarted = false;

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM)
		{
			return;
		}

		String chatMessage = event.getMessage();
		if (chatMessage.startsWith(COLLECTION_LOG_TEXT) &&
			client.getVarbitValue(Varbits.COLLECTION_LOG_NOTIFICATION) == 1)
		{
			String entry = Text.removeTags(chatMessage).substring(COLLECTION_LOG_TEXT.length());
			reportCollectionLogEntry(entry, chatMessage, DetectionMethod.CHAT_COLLECTION_LOG);
		}
	}

	@Subscribe
	public void onScriptPreFired(ScriptPreFired event)
	{
		switch (event.getScriptId())
		{
			case ScriptID.NOTIFICATION_START:
				notificationStarted = true;
				break;
			case ScriptID.NOTIFICATION_DELAY:
				if (!notificationStarted)
				{
					return;
				}
				String notificationTopText = client.getVarcStrValue(VarClientStr.NOTIFICATION_TOP_TEXT);
				String notificationBottomText = client.getVarcStrValue(VarClientStr.NOTIFICATION_BOTTOM_TEXT);
				if (notificationTopText.equalsIgnoreCase("Collection log"))
				{
					String entry = Text.removeTags(notificationBottomText).substring("New item:".length()).trim();
					reportCollectionLogEntry(entry, notificationBottomText, DetectionMethod.NOTIFICATION_COLLECTION_LOG);
				}
				notificationStarted = false;
				break;
		}
	}

	private void reportCollectionLogEntry(String itemName, String rawText, DetectionMethod method)
	{
		DropItem dropItem = DropItem.builder()
			.name(itemName)
			.quantity(1)
			.build();

		screenshotService.requestScreenshot(image -> executor.execute(() -> {
			DropSignal signal = DropSignal.builder()
				.detectionMethod(method)
				.raw(rawText)
				.items(Collections.singletonList(dropItem))
				.screenshot(image)
				.build();
			dropCorrelationService.report(signal);
		}));
	}

	public void resetState()
	{
		notificationStarted = false;
	}
}

package com.fauxbingo.handlers;

import com.fauxbingo.services.EventsApiService;
import com.fauxbingo.services.InteractionTrackingService;
import com.fauxbingo.services.data.DeathSignal;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.eventbus.Subscribe;

/**
 * Handles player death. Submits a DEATH envelope to EventsApiService (batched, per the v1
 * contract - there's no dedicated death endpoint any more). Uses InteractionTrackingService for
 * killer detection.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class DeathHandler
{
	private final Client client;
	private final EventsApiService eventsApiService;
	private final InteractionTrackingService interactionTrackingService;

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		Actor local = client.getLocalPlayer();
		if (local == null || local != event.getActor())
		{
			return;
		}

		int regionId = 0;
		String killer = null;
		String killerKind = "UNKNOWN";

		try
		{
			WorldPoint loc = local.getWorldLocation();
			if (loc != null)
			{
				regionId = loc.getRegionID();
			}
		}
		catch (Exception e)
		{
			log.debug("Could not get death location", e);
		}

		Actor candidate = (interactionTrackingService != null) ? interactionTrackingService.getLastTarget() : null;
		if (candidate == null)
		{
			candidate = local.getInteracting();
		}
		if (candidate != null && candidate != local)
		{
			String name = candidate.getName();
			if (name != null && !name.isEmpty())
			{
				killer = name;
				killerKind = candidate instanceof Player ? "PLAYER" : candidate instanceof NPC ? "NPC" : "UNKNOWN";
			}
		}

		DeathSignal signal = DeathSignal.builder()
			.regionId(regionId)
			.killerName(killer)
			.killerKind(killerKind)
			.build();

		eventsApiService.submitDeath(signal);
	}
}

package com.fauxbingo.handlers;

import com.fauxbingo.services.DropCorrelationService;
import com.fauxbingo.services.ScreenshotService;
import com.fauxbingo.services.data.DetectionMethod;
import com.fauxbingo.services.data.DropItem;
import com.fauxbingo.services.data.DropSignal;
import com.fauxbingo.services.data.SourceKind;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Deque;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.NPCComposition;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.events.PlayerLootReceived;
import net.runelite.client.events.ServerNpcLoot;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.http.api.loottracker.LootRecordType;

/**
 * Handles loot-related events from NPCs, players, and non-combat sources. Builds one DropSignal
 * per detection and hands it to DropCorrelationService, which decides whether it gets merged
 * with corroborating signals from other handlers (valuable drop chat, collection log, pet)
 * before anything is sent to the API.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class LootEventHandler
{
	/**
	 * How long a kill stays eligible to be paired with its counterpart event.
	 */
	private static final long PAIRING_WINDOW_MS = 5_000;

	private enum NpcLootSignal
	{
		TILE_SCAN,
		SERVER;

		NpcLootSignal other()
		{
			return this == TILE_SCAN ? SERVER : TILE_SCAN;
		}
	}

	/**
	 * Kills seen through one NPC loot event and still waiting for the other. This is the
	 * same-method dedup layer (NpcLootReceived vs ServerNpcLoot for one real kill) and stays
	 * separate from DropCorrelationService's cross-method merge.
	 */
	private final Deque<SeenKill> unpairedKills = new ArrayDeque<>();

	private static class SeenKill
	{
		private final String source;
		private final Map<Integer, Integer> totals;
		private final NpcLootSignal signal;
		private final long timestamp;

		SeenKill(String source, Map<Integer, Integer> totals, NpcLootSignal signal, long timestamp)
		{
			this.source = source;
			this.totals = totals;
			this.signal = signal;
			this.timestamp = timestamp;
		}
	}

	/** One deferred LOOT_TRACKER_EVENT, held until the tick's remaining container changes land. */
	private static class PendingEventLoot
	{
		private final String source;
		private final Collection<ItemStack> items;

		PendingEventLoot(String source, Collection<ItemStack> items)
		{
			this.source = source;
			this.items = items;
		}
	}

	private final ItemManager itemManager;
	private final ScreenshotService screenshotService;
	private final ScheduledExecutorService executor;
	private final DropCorrelationService dropCorrelationService;
	private final Client client;

	/** Item id to count for the equipment container, as of the last change to it. */
	private final Map<Integer, Integer> wornItems = new HashMap<>();

	/** False until wornItems has been populated at least once, so the first diff isn't against nothing. */
	private boolean wornKnown = false;

	/** Item id to count for everything that left the equipment container this tick. */
	private final Map<Integer, Integer> unequippedThisTick = new HashMap<>();

	private final List<PendingEventLoot> pendingEventLoot = new ArrayList<>();

	@Subscribe
	public void onNpcLootReceived(NpcLootReceived event)
	{
		Integer npcId = event.getNpc() != null ? event.getNpc().getId() : null;
		Integer combatLevel = event.getNpc() != null ? event.getNpc().getCombatLevel() : null;
		processNpcLoot(event.getNpc().getName(), event.getItems(), NpcLootSignal.TILE_SCAN, npcId, combatLevel);
	}

	@Subscribe
	public void onPlayerLootReceived(PlayerLootReceived event)
	{
		processLoot(event.getPlayer().getName(), event.getItems(), SourceKind.PLAYER,
			DetectionMethod.PLAYER_LOOT_RECEIVED, null, null);
	}

	/**
	 * The server driven counterpart to NpcLootReceived. Bosses whose loot does not land on their own
	 * tile (Yama at his throne for example) have no case in LootManager's getDropLocations, 
	 * so this is the only event they ever produce.
	 */
	@Subscribe
	public void onServerNpcLoot(ServerNpcLoot event)
	{
		NPCComposition npc = event.getComposition();
		Integer npcId = npc != null ? npc.getId() : null;
		Integer combatLevel = npc != null ? npc.getCombatLevel() : null;
		processNpcLoot(npc != null ? npc.getName() : null, event.getItems(), NpcLootSignal.SERVER, npcId, combatLevel);
	}

	/**
	 * Most kills fire both NPC loot events, so the first one through wins and the second is paired
	 * off against it. Pairing consumes a single entry rather than suppressing everything with a
	 * matching kill, so back to back kills of the same NPC with identical loot still report once each.
	 */
	private void processNpcLoot(String source, Collection<ItemStack> items, NpcLootSignal signal, Integer npcId, Integer combatLevel)
	{
		if (items == null || items.isEmpty())
		{
			return;
		}

		Map<Integer, Integer> totals = itemTotals(items);
		long now = System.currentTimeMillis();
		dropStaleKills(now);

		SeenKill pair = findPair(source, totals, signal);
		if (pair != null)
		{
			unpairedKills.remove(pair);
			log.debug("Skipping {} loot for {}, already reported via {}", signal, source, pair.signal);
			return;
		}

		unpairedKills.add(new SeenKill(source, totals, signal, now));
		DetectionMethod method = signal == NpcLootSignal.TILE_SCAN
			? DetectionMethod.NPC_LOOT_RECEIVED
			: DetectionMethod.SERVER_NPC_LOOT;
		processLoot(source, items, SourceKind.NPC, method, npcId, combatLevel);
	}

	/**
	 * An identical loot list is the normal pair. Failing that, one list holding nothing the other
	 * lacks still pairs: the tile scan only sees what reached the ground, so a bonecrusher eating a
	 * Mithril dragon's Dragon bones leaves it one item short of the server's list for the same kill.
	 * Last, the lists may each hold something the other lacks, as long as every such item is one
	 * the two events are known to disagree on (see isOneSidedItem). A Scurrius kill arrived as one
	 * list without its Big bones and the other without its Scroll box (medium).
	 * Each tier is tried in full before the next so a looser match can't steal the pair of a
	 * tighter one queued behind it.
	 */
	private SeenKill findPair(String source, Map<Integer, Integer> totals, NpcLootSignal signal)
	{
		SeenKill subsetMatch = null;
		SeenKill oneSidedMatch = null;
		for (SeenKill seen : unpairedKills)
		{
			if (seen.signal != signal.other() || !Objects.equals(seen.source, source))
			{
				continue;
			}
			if (seen.totals.equals(totals))
			{
				return seen;
			}
			if (subsetMatch == null && (containedIn(seen.totals, totals) || containedIn(totals, seen.totals)))
			{
				subsetMatch = seen;
			}
			if (oneSidedMatch == null && differsOnlyInOneSidedItems(seen.totals, totals))
			{
				oneSidedMatch = seen;
			}
		}
		return subsetMatch != null ? subsetMatch : oneSidedMatch;
	}

	/**
	 * True when the lists share at least one item at the same count and every item whose count
	 * differs is one-sided. Anything else differing, like Oathplate shards on one side and Chaos
	 * runes on the other, still means two kills.
	 */
	private boolean differsOnlyInOneSidedItems(Map<Integer, Integer> a, Map<Integer, Integer> b)
	{
		Set<Integer> ids = new HashSet<>(a.keySet());
		ids.addAll(b.keySet());

		boolean shared = false;
		for (int id : ids)
		{
			int countA = a.getOrDefault(id, 0);
			int countB = b.getOrDefault(id, 0);
			if (countA == countB)
			{
				shared = true;
			}
			else if (!isOneSidedItem(id))
			{
				return false;
			}
		}
		return shared;
	}

	/**
	 * Items one NPC loot event can list while the other leaves them out for the same kill. Bones and
	 * ashes never reach the ground under a bonecrusher or ash sanctifier, so the tile scan misses
	 * them. Clue scroll boxes and clue scrolls can show up in one list and be absent from the other.
	 */
	private boolean isOneSidedItem(int itemId)
	{
		ItemComposition composition = itemManager.getItemComposition(itemId);
		String name = composition != null ? composition.getName() : null;
		if (name == null)
		{
			return false;
		}
		name = name.toLowerCase(Locale.ROOT);
		return name.endsWith("bones")
			|| name.endsWith("ashes")
			|| name.startsWith("scroll box (")
			|| name.startsWith("clue scroll (");
	}

	/** True when every item in part appears in whole with at least the same count. */
	private static boolean containedIn(Map<Integer, Integer> part, Map<Integer, Integer> whole)
	{
		for (Map.Entry<Integer, Integer> entry : part.entrySet())
		{
			if (whole.getOrDefault(entry.getKey(), 0) < entry.getValue())
			{
				return false;
			}
		}
		return true;
	}

	private void dropStaleKills(long now)
	{
		while (!unpairedKills.isEmpty() && now - unpairedKills.peek().timestamp > PAIRING_WINDOW_MS)
		{
			unpairedKills.poll();
		}
	}

	/**
	 * Item id to count, order and stacking independent so both events describe a kill the same way.
	 * Quantities are summed per item because the two events don't stack non-stackables the same
	 * way: a Mithril dragon's three bars arrive as three 1x stacks in one and a single 3x in the other.
	 */
	private static Map<Integer, Integer> itemTotals(Collection<ItemStack> items)
	{
		Map<Integer, Integer> totals = new HashMap<>();
		for (ItemStack item : items)
		{
			totals.merge(item.getId(), item.getQuantity(), Integer::sum);
		}
		return totals;
	}

	/**
	 * Non-combat loot (Tempoross reward pool, Wintertodt crates, clue caskets, chests, Guardians of
	 * the Rift, and friends) never produces an NpcLootReceived. It only surfaces as a LootReceived
	 * from the Loot Tracker plugin, so this is the only way we see any of it.
	 *
	 * Queued rather than reported here: LootTrackerPlugin derives these items by diffing the
	 * inventory, so anything else that entered the inventory on this tick is in the list too. The
	 * gear a player swaps off between kills is the common case - a Tarnished bracelet cleaned on
	 * the same tick as a weapon switch reported the weapon as loot. onGameTick subtracts it.
	 */
	@Subscribe
	public void onLootReceived(LootReceived event)
	{
		// NPC and player kills already reach us through LootManager
		if (event.getType() != LootRecordType.EVENT)
		{
			return;
		}

		Collection<ItemStack> items = event.getItems();
		if (items == null || items.isEmpty())
		{
			return;
		}

		pendingEventLoot.add(new PendingEventLoot(event.getName(), items));
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() != InventoryID.WORN)
		{
			return;
		}

		Map<Integer, Integer> current = countItems(event.getItemContainer());

		if (wornKnown)
		{
			for (Map.Entry<Integer, Integer> entry : wornItems.entrySet())
			{
				int removed = entry.getValue() - current.getOrDefault(entry.getKey(), 0);
				if (removed > 0)
				{
					unequippedThisTick.merge(entry.getKey(), removed, Integer::sum);
				}
			}
		}

		wornItems.clear();
		wornItems.putAll(current);
		wornKnown = true;
	}

	/**
	 * GameTick fires after all of the tick's packets have been processed, so by here both the
	 * inventory change that produced the loot and the equipment change that ran alongside it have
	 * been seen, whatever order the server sent them in.
	 */
	@Subscribe
	public void onGameTick(GameTick event)
	{
		// Seeds wornItems when the plugin starts mid-session, so the player's first gear swap after
		// startup is diffed against real equipment rather than an empty map.
		if (!wornKnown)
		{
			ItemContainer worn = client.getItemContainer(InventoryID.WORN);
			if (worn != null)
			{
				wornItems.putAll(countItems(worn));
				wornKnown = true;
			}
		}

		for (PendingEventLoot pending : pendingEventLoot)
		{
			Collection<ItemStack> items = withoutUnequipped(pending.source, pending.items);
			if (!items.isEmpty())
			{
				processLoot(pending.source, items, SourceKind.OTHER, DetectionMethod.LOOT_TRACKER_EVENT, null, null);
			}
		}

		pendingEventLoot.clear();
		unequippedThisTick.clear();
	}

	/**
	 * Drops as much of each stack as the equipment container lost this tick. Subtracting the count
	 * rather than the whole stack keeps a genuine drop of an item the player also unequipped: come
	 * back from a crate with two Tomes of fire having taken one off, and one is still loot.
	 */
	private Collection<ItemStack> withoutUnequipped(String source, Collection<ItemStack> items)
	{
		if (unequippedThisTick.isEmpty())
		{
			return items;
		}

		Map<Integer, Integer> budget = new HashMap<>(unequippedThisTick);
		List<ItemStack> kept = new ArrayList<>(items.size());

		for (ItemStack item : items)
		{
			int available = budget.getOrDefault(item.getId(), 0);
			int subtract = Math.min(item.getQuantity(), available);

			if (subtract > 0)
			{
				budget.put(item.getId(), available - subtract);
				log.debug("Dropping {} x {} from {} loot, unequipped this tick", subtract, item.getId(), source);
			}

			int remaining = item.getQuantity() - subtract;
			if (remaining > 0)
			{
				kept.add(new ItemStack(item.getId(), remaining));
			}
		}

		return kept;
	}

	/** Empty slots come through as id -1 or quantity 0 and are left out. */
	private static Map<Integer, Integer> countItems(ItemContainer container)
	{
		Map<Integer, Integer> counts = new HashMap<>();
		if (container == null)
		{
			return counts;
		}

		for (Item item : container.getItems())
		{
			if (item.getId() > 0 && item.getQuantity() > 0)
			{
				counts.merge(item.getId(), item.getQuantity(), Integer::sum);
			}
		}

		return counts;
	}

	private void processLoot(String source, Collection<ItemStack> items, SourceKind sourceKind,
		DetectionMethod method, Integer npcId, Integer combatLevel)
	{
		long totalValue = 0;
		List<DropItem> dropItems = new ArrayList<>(items.size());

		for (ItemStack itemStack : items)
		{
			int itemId = itemStack.getId();
			int quantity = itemStack.getQuantity();
			long price = itemManager.getItemPrice(itemId);
			totalValue += price * quantity;

			String itemName = itemManager.getItemComposition(itemId).getName();

			dropItems.add(DropItem.builder()
				.id(itemId)
				.name(itemName)
				.quantity(quantity)
				.unitPriceGe(price)
				.build());
		}

		long finalTotalValue = totalValue;

		// Read now, not from inside the async screenshot callback, so it reflects where the drop
		// actually happened rather than wherever the player has walked to by the time it fires.
		WorldPoint location = client.getLocalPlayer() != null ? client.getLocalPlayer().getWorldLocation() : null;
		Integer regionId = location != null ? location.getRegionID() : null;
		Integer plane = location != null ? location.getPlane() : null;

		// Captured immediately regardless of value, DropCorrelationService may still merge this
		// with a corroborating signal from another handler before either reaches the API.
		screenshotService.requestScreenshot(image -> executor.execute(() -> {
			DropSignal signal = DropSignal.builder()
				.detectionMethod(method)
				.sourceKind(sourceKind)
				.sourceName(source)
				.npcId(npcId)
				.combatLevel(combatLevel)
				.regionId(regionId)
				.plane(plane)
				.items(dropItems)
				.totalValueGe(finalTotalValue)
				.screenshot(image)
				.build();
			dropCorrelationService.report(signal);
		}));
	}
}

package com.fauxbingo.handlers;

import com.fauxbingo.services.DropCorrelationService;
import com.fauxbingo.services.InteractionTrackingService;
import com.fauxbingo.services.ScreenshotService;
import com.fauxbingo.services.data.DetectionMethod;
import com.fauxbingo.services.data.DropSignal;
import com.google.common.collect.ImmutableList;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.eventbus.Subscribe;

/**
 * Handles chat message events to detect pet drops. The game never names the pet in this message,
 * so the signal carries no item identity - DropCorrelationService learns the name later if a
 * COLLECTION_LOG signal lands in the same correlation window (docs/bingo-events-api.md section 6.3).
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class PetChatHandler
{
	private static final ImmutableList<String> PET_MESSAGES = ImmutableList.of(
		"You have a funny feeling like you're being followed",
		"You feel something weird sneaking into your backpack",
		"You have a funny feeling like you would have been followed"
	);

	private final ScreenshotService screenshotService;
	private final ScheduledExecutorService executor;
	private final DropCorrelationService dropCorrelationService;
	private final InteractionTrackingService interactionTrackingService;

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM)
		{
			return;
		}

		String message = event.getMessage();

		// Check if message indicates a pet drop
		if (PET_MESSAGES.stream().anyMatch(message::contains))
		{
			handlePetDrop(message);
		}
	}

	private void handlePetDrop(String rawChatLine)
	{
		log.info("Pet drop detected");

		// Best guess at what the pet came from; the plugin has no better signal than this.
		List<String> recentInteractions = interactionTrackingService != null
			? interactionTrackingService.getRecentInteractionNames()
			: List.of();
		String sourceNameGuess = recentInteractions.isEmpty() ? null : recentInteractions.get(0);

		screenshotService.requestScreenshot(image -> executor.execute(() -> {
			DropSignal signal = DropSignal.builder()
				.detectionMethod(DetectionMethod.CHAT_PET)
				.raw(rawChatLine)
				.sourceNameGuess(sourceNameGuess)
				.screenshot(image)
				.build();
			dropCorrelationService.report(signal);
		}));
	}
}

package com.fauxbingo.handlers;

import com.fauxbingo.services.DropCorrelationService;
import com.fauxbingo.services.ScreenshotService;
import com.fauxbingo.services.data.DetectionMethod;
import com.fauxbingo.services.data.DropItem;
import com.fauxbingo.services.data.DropSignal;
import com.fauxbingo.services.data.SourceKind;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.Text;

/**
 * Handles raid loot notifications for Chambers of Xeric and Theatre of Blood.
 * Tracks raid completions and unique drops from both raids, and assembles them into one
 * DropSignal per chest - the chat rare/KC assembly happens here because its own timing (chat
 * line to chest open can be many seconds) doesn't fit DropCorrelationService's shorter
 * cross-handler window.
 *
 * The `raidProcessed` latch used to re-arm itself after 60s of inactivity, on the theory that a
 * widget reload after a long gap meant a new attempt. It doesn't: the reward interface can
 * reload for the *same* chest while the player is still standing in front of it (e.g. only
 * getting round to opening it long after the loot screen first populated), which re-armed the
 * latch and let the next ItemContainerChanged for that same, unchanged container report the
 * identical loot a second time. The bundled LootTrackerPlugin's `chestLooted` latch never has
 * this problem because it only resets on a real boundary - entering or leaving an instanced
 * region - so that's what this mirrors instead of a timer.
 *
 * Chambers of Xeric announces its loot in chat when Olm dies, but the chest can be opened any
 * amount of time later, so DropCorrelationService is told to hold chat-only groups open for as
 * long as the player is inside the raid. Nothing else that produces loot can happen before they
 * leave it. The varbit is read every tick rather than trusted to report its own change, so a
 * plugin started mid-raid, or a missed change, can't leave the hold in the wrong state.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class RaidLootHandler
{
	private static final Pattern COX_UNIQUE_MESSAGE_PATTERN = Pattern.compile("(.+) - (.+)");
	private static final String COX_DUST_MESSAGE_TEXT = "Dust recipients: ";
	private static final String COX_KIT_MESSAGE_TEXT = "Twisted Kit recipients: ";
	private static final Pattern TOB_UNIQUE_MESSAGE_PATTERN = Pattern.compile("(.+) found something special: (.+)");
	private static final Pattern TOA_UNIQUE_MESSAGE_PATTERN = Pattern.compile("Loot recipient: (.+) - (.+)");
	private static final Pattern KC_MESSAGE_PATTERN = Pattern.compile("([0-9]+)");

	private static final int CoX_Interface_Id = InterfaceID.RAIDS_REWARDS;
	private static final int ToB_Interface_Id = InterfaceID.TOB_CHESTS;
	private static final int ToA_Interface_Id = 775; // InterfaceID.TOA_REWARD_CHEST might not be available in all versions

	private static final int CoX_Container_Id = 581;
	private static final int ToB_Container_Id = 612;
	private static final int ToA_Container_Id = 801;

	enum RaidType
	{
		COX,
		COX_CM,
		TOB,
		TOB_SM,
		TOB_HM,
		TOA_ENTRY,
		TOA_NORMAL,
		TOA_EXPERT
	}

	private final Client client;
	private final ScreenshotService screenshotService;
	private final ScheduledExecutorService executor;
	private final ItemManager itemManager;
	private final DropCorrelationService dropCorrelationService;

	private RaidType raidType;
	private Integer raidKc;
	private final List<String> rareDrops = new ArrayList<>();
	private boolean raidProcessed = false;
	private boolean inInstancedRegion = false;
	private boolean inChambers = false;

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE
			&& event.getType() != ChatMessageType.SPAM
			&& event.getType() != ChatMessageType.TRADE
			&& event.getType() != ChatMessageType.FRIENDSCHATNOTIFICATION)
		{
			return;
		}

		handleRaidChatMessage(event.getMessage());
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		setInChambers(client.getVarbitValue(VarbitID.RAIDS_CLIENT_INDUNGEON) == 1);
	}

	private void setInChambers(boolean nowInChambers)
	{
		if (nowInChambers == inChambers)
		{
			return;
		}
		inChambers = nowInChambers;
		if (nowInChambers)
		{
			dropCorrelationService.holdNewGroups();
		}
		else
		{
			dropCorrelationService.releaseHeldGroups();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		// Logging out ends the raid without the varbit necessarily reporting it.
		if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			setInChambers(false);
		}

		// Mirrors LootTrackerPlugin's `chestLooted` reset: the latch only re-arms on a genuine
		// boundary (entering or leaving an instance), never on elapsed time, so a chest the player
		// is still standing in front of can't be reported twice just because they took a while to
		// open it.
		boolean nowInInstancedRegion = client.isInInstancedRegion();
		if (event.getGameState() == GameState.LOADING && nowInInstancedRegion != inInstancedRegion)
		{
			inInstancedRegion = nowInInstancedRegion;
			raidProcessed = false;
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		int containerId = event.getContainerId();
		if (containerId == CoX_Container_Id || containerId == ToB_Container_Id || containerId == ToA_Container_Id)
		{
			handleRaidInventory(containerId, event.getItemContainer());
		}
	}

	private void handleRaidChatMessage(String chatMessage)
	{
		String cleanMessage = Text.removeTags(chatMessage);

		// Check for completion messages - these mark the start of a new raid loot sequence
		if (cleanMessage.startsWith("Your completed Chambers of Xeric count is:") ||
			cleanMessage.startsWith("Your completed Theatre of Blood") ||
			(cleanMessage.contains("Tombs of Amascut") && cleanMessage.contains("completion count is")))
		{
			// Reset state for new raid loot
			resetState();
		}

		// Check for COX completion
		if (cleanMessage.startsWith("Your completed Chambers of Xeric count is:"))
		{
			Matcher matcher = KC_MESSAGE_PATTERN.matcher(cleanMessage);
			if (matcher.find())
			{
				raidType = cleanMessage.contains("Challenge Mode") ? RaidType.COX_CM : RaidType.COX;
				raidKc = Integer.valueOf(matcher.group());
				return;
			}
		}

		// Check for TOB completion
		if (cleanMessage.startsWith("Your completed Theatre of Blood"))
		{
			Matcher matcher = KC_MESSAGE_PATTERN.matcher(cleanMessage);
			if (matcher.find())
			{
				raidType = cleanMessage.contains("Hard Mode") ? RaidType.TOB_HM :
					(cleanMessage.contains("Story Mode") ? RaidType.TOB_SM : RaidType.TOB);
				raidKc = Integer.valueOf(matcher.group());
				return;
			}
		}

		// Check for TOA completion
		if (cleanMessage.contains("Tombs of Amascut") && cleanMessage.contains("completion count is"))
		{
			Matcher matcher = KC_MESSAGE_PATTERN.matcher(cleanMessage);
			if (matcher.find())
			{
				if (cleanMessage.contains("Expert Mode"))
				{
					raidType = RaidType.TOA_EXPERT;
				}
				else if (cleanMessage.contains("Entry Mode"))
				{
					raidType = RaidType.TOA_ENTRY;
				}
				else
				{
					raidType = RaidType.TOA_NORMAL;
				}
				raidKc = Integer.valueOf(matcher.group());
				return;
			}
		}

		// Check for TOA unique drops
		Matcher toaUnique = TOA_UNIQUE_MESSAGE_PATTERN.matcher(chatMessage);
		if (toaUnique.matches())
		{
			final String lootRecipient = Text.sanitize(toaUnique.group(1)).trim();
			if (lootRecipient.equalsIgnoreCase(getLocalPlayerName()))
			{
				rareDrops.add(toaUnique.group(2).trim());
			}
			return;
		}

		// Check for COX unique drops
		Matcher coxUnique = COX_UNIQUE_MESSAGE_PATTERN.matcher(chatMessage);
		if (coxUnique.matches())
		{
			final String lootRecipient = Text.sanitize(coxUnique.group(1)).trim();
			if (lootRecipient.equalsIgnoreCase(getLocalPlayerName()))
			{
				rareDrops.add(coxUnique.group(2).trim());
			}
			return;
		}

		// Check for COX metamorphic dust
		if (cleanMessage.startsWith(COX_DUST_MESSAGE_TEXT))
		{
			if (cleanMessage.toLowerCase().contains(getLocalPlayerName().toLowerCase()))
			{
				rareDrops.add("Metamorphic dust");
			}
			return;
		}

		// Check for COX twisted kit
		if (cleanMessage.startsWith(COX_KIT_MESSAGE_TEXT))
		{
			if (cleanMessage.toLowerCase().contains(getLocalPlayerName().toLowerCase()))
			{
				rareDrops.add("Twisted ancestral colour kit");
			}
			return;
		}

		// Check for TOB unique drops
		Matcher tobUnique = TOB_UNIQUE_MESSAGE_PATTERN.matcher(chatMessage);
		if (tobUnique.matches())
		{
			final String lootRecipient = Text.sanitize(tobUnique.group(1)).trim();
			if (lootRecipient.equalsIgnoreCase(getLocalPlayerName()))
			{
				rareDrops.add(tobUnique.group(2).trim());
			}
			return;
		}
	}

	private void handleRaidInventory(int containerId, ItemContainer itemContainer)
	{
		if (itemContainer == null || raidProcessed)
		{
			return;
		}

		String raidName = getRaidName(containerId);
		if (raidName == null)
		{
			return;
		}

		// Only process if container has items
		Item[] items = itemContainer.getItems();
		if (items == null || items.length == 0 || Arrays.stream(items).allMatch(i -> i.getId() == -1))
		{
			return;
		}

		try
		{
			processRaidLoot(raidName, itemContainer);
		}
		finally
		{
			// Clear per-raid rare drop state after loot is processed to avoid replaying on later chests.
			rareDrops.clear();
		}
		raidProcessed = true;
	}

	private void processRaidLoot(String raidName, ItemContainer itemContainer)
	{
		long totalValue = 0;
		List<DropItem> allItems = new ArrayList<>();

		for (Item item : itemContainer.getItems())
		{
			int itemId = item.getId();
			if (itemId != -1)
			{
				String itemName = itemManager.getItemComposition(itemId).getName();
				int quantity = item.getQuantity();
				long price = itemManager.getItemPrice(itemId);
				totalValue += price * quantity;

				allItems.add(DropItem.builder()
					.id(itemId)
					.name(itemName)
					.quantity(quantity)
					.unitPriceGe(price)
					.build());
			}
		}

		reportRaidLoot(raidName, allItems, totalValue);
	}

	private void reportRaidLoot(String raidName, List<DropItem> allItems, long totalValue)
	{
		Integer kc = raidKc;
		String variant = raidType != null ? raidType.name() : null;

		// Read now rather than from inside the async screenshot callback below, same reasoning
		// as LootEventHandler: reflects the raid room, not wherever the player walks to next.
		WorldPoint location = client.getLocalPlayer() != null ? client.getLocalPlayer().getWorldLocation() : null;
		Integer regionId = location != null ? location.getRegionID() : null;
		Integer plane = location != null ? location.getPlane() : null;

		screenshotService.requestScreenshot(image -> executor.execute(() -> {
			DropSignal signal = DropSignal.builder()
				.detectionMethod(DetectionMethod.RAID_CHEST_CONTAINER)
				.sourceKind(SourceKind.RAID)
				.sourceName(raidName)
				.killCount(kc)
				.variant(variant)
				.regionId(regionId)
				.plane(plane)
				.items(allItems)
				.totalValueGe(totalValue)
				.screenshot(image)
				.build();
			dropCorrelationService.report(signal);
		}));
	}

	private String getRaidName(int id)
	{
		if (id == CoX_Interface_Id || id == CoX_Container_Id)
		{
			if (raidType == RaidType.COX_CM)
			{
				return "Chambers of Xeric Challenge Mode";
			}
			return "Chambers of Xeric";
		}
		else if (id == ToB_Interface_Id || id == ToB_Container_Id)
		{
			if (raidType == RaidType.TOB_SM)
			{
				return "Theatre of Blood Story Mode";
			}
			else if (raidType == RaidType.TOB_HM)
			{
				return "Theatre of Blood Hard Mode";
			}
			return "Theatre of Blood";
		}
		else if (id == ToA_Interface_Id || id == ToA_Container_Id)
		{
			if (raidType == RaidType.TOA_EXPERT)
			{
				return "Tombs of Amascut Expert Mode";
			}
			else if (raidType == RaidType.TOA_ENTRY)
			{
				return "Tombs of Amascut Entry Mode";
			}
			return "Tombs of Amascut";
		}
		return null;
	}

	public void resetState()
	{
		raidType = null;
		raidKc = null;
		rareDrops.clear();
	}

	private String getLocalPlayerName()
	{
		return client.getLocalPlayer() != null ? Text.sanitize(client.getLocalPlayer().getName()) : "Player";
	}
}

package com.fauxbingo.handlers;

import com.fauxbingo.services.DropCorrelationService;
import com.fauxbingo.services.ScreenshotService;
import com.fauxbingo.services.data.DetectionMethod;
import com.fauxbingo.services.data.DropItem;
import com.fauxbingo.services.data.DropSignal;
import com.fauxbingo.services.data.SourceKind;
import java.util.Collections;
import java.util.concurrent.ScheduledExecutorService;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.eventbus.Subscribe;

/**
 * Handles valuable drop notifications from chat messages. Detects when the game announces a
 * valuable drop and reports it to DropCorrelationService, which decides whether it stands alone
 * or corroborates a LOOT signal from LootEventHandler/RaidLootHandler for the same item.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class ValuableDropHandler
{
	/**
	 * The name is captured apart from the trailing coin value because it can hold parentheses of
	 * its own: "Craw's bow (u) (14,400,000 coins)" is still named "Craw's bow (u)".
	 */
	private static final Pattern VALUABLE_DROP_PATTERN = Pattern.compile(
		".*Valuable drop: ([^<>]+?) \\(((?:\\d+,?)+) coins\\)(?:</col>)?"
	);

	/** The chat line embeds quantity in the name, as in "30 x Dragon bones". */
	private static final Pattern QUANTITY_PREFIX = Pattern.compile("^([0-9,]+) x ");

	private final ScreenshotService screenshotService;
	private final ScheduledExecutorService executor;
	private final DropCorrelationService dropCorrelationService;

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM)
		{
			return;
		}

		String chatMessage = event.getMessage();
		Matcher matcher = VALUABLE_DROP_PATTERN.matcher(chatMessage);

		if (matcher.matches())
		{
			long valuableDropValue = Long.parseLong(matcher.group(2).replaceAll(",", ""));
			String valuableDropNameWithQuantity = matcher.group(1);
			reportValuableDrop(chatMessage, valuableDropNameWithQuantity, valuableDropValue);
		}
	}

	private void reportValuableDrop(String rawChatLine, String itemNameWithQuantity, long value)
	{
		String itemName = cleanItemName(itemNameWithQuantity);
		int quantity = parseQuantity(itemNameWithQuantity);

		DropItem dropItem = DropItem.builder()
			.name(itemName)
			.quantity(quantity)
			.unitPriceGe(quantity > 0 ? value / quantity : value)
			.build();

		screenshotService.requestScreenshot(image -> executor.execute(() -> {
			DropSignal signal = DropSignal.builder()
				.detectionMethod(DetectionMethod.CHAT_VALUABLE_DROP)
				.raw(rawChatLine)
				.sourceKind(SourceKind.OTHER)
				.items(Collections.singletonList(dropItem))
				.totalValueGe(value)
				.screenshot(image)
				.build();
			dropCorrelationService.report(signal);
		}));
	}

	private String cleanItemName(String itemName)
	{
		if (itemName == null)
		{
			return null;
		}
		// Strip quantity prefix like "30 x " or "1,000 x " to help with bundling across different handlers
		return QUANTITY_PREFIX.matcher(itemName).replaceFirst("");
	}

	/** The chat text is the only source for quantity, so parse it out rather than assuming 1. */
	private static int parseQuantity(String itemNameWithQuantity)
	{
		Matcher matcher = QUANTITY_PREFIX.matcher(itemNameWithQuantity);
		if (!matcher.find())
		{
			return 1;
		}
		try
		{
			return Math.max(1, Integer.parseInt(matcher.group(1).replaceAll(",", "")));
		}
		catch (NumberFormatException e)
		{
			return 1;
		}
	}
}

package com.fauxbingo.overlay;

import com.fauxbingo.FauxBingoConfig;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.List;
import java.util.TimeZone;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayMenuEntry;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;
import net.runelite.client.ui.overlay.components.LineComponent;
import static net.runelite.api.MenuAction.RUNELITE_OVERLAY_CONFIG;
import static net.runelite.client.ui.overlay.OverlayManager.OPTION_CONFIGURE;

/**
 * Overlay that displays team name and current date/time in UTC.
 * Used for verification purposes when screenshots are sent to Discord webhooks.
 */
public class TeamOverlay extends OverlayPanel
{
	private final FauxBingoConfig config;

	@Inject
	public TeamOverlay(FauxBingoConfig config)
	{
		this.config = config;
		setPosition(OverlayPosition.TOP_CENTER);
		getMenuEntries().add(new OverlayMenuEntry(RUNELITE_OVERLAY_CONFIG, OPTION_CONFIGURE, "Faux Bingo overlay"));
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		// Only render if overlay is enabled and team name is set
		if (!config.displayOverlay() || config.teamName().trim().isEmpty())
		{
			return null;
		}

		String teamName = config.teamName();
		Color teamNameColor = config.teamNameColor();
		Color dateTimeColor = config.dateTimeColor();

		// Ensure colors are different, fallback to defaults if they match
		if (teamNameColor.equals(dateTimeColor))
		{
			teamNameColor = Color.GREEN;
			dateTimeColor = Color.WHITE;
		}

		// Build the full text for width calculation
		String fullText = teamName;
		if (config.displayDateTime())
		{
			fullText = teamName + " " + getUtcDateTime();
		}

		// Add team name as the left component
		panelComponent.getChildren().add(LineComponent.builder()
			.left(teamName)
			.leftColor(teamNameColor)
			.build());

		// Add date/time as the right component if enabled
		if (config.displayDateTime())
		{
			List<LayoutableRenderableEntity> children = panelComponent.getChildren();
			LineComponent line = (LineComponent) children.get(0);
			line.setRight(getUtcDateTime());
			line.setRightColor(dateTimeColor);
		}

		// Set preferred size based on text width
		panelComponent.setPreferredSize(new Dimension(
			graphics.getFontMetrics().stringWidth(fullText) + 10, 0));

		return super.render(graphics);
	}

	private String getUtcDateTime()
	{
		Date date = new Date();
		SimpleDateFormat sdf = new SimpleDateFormat("dd/MM/yyyy HH:mm");
		sdf.setTimeZone(TimeZone.getTimeZone("UTC"));
		return sdf.format(date) + " UTC";
	}
}

package com.fauxbingo.services;

import okhttp3.HttpUrl;

/**
 * Cleans the API token and base URL, which users paste in by hand.
 *
 * invisible characters - a non-breaking space, a zero-width space, a BOM.
 */
public final class ApiConfigSanitizer
{
	private ApiConfigSanitizer()
	{
	}

	public static String sanitize(String raw)
	{
		if (raw == null)
		{
			return "";
		}

		StringBuilder cleaned = new StringBuilder(raw.length());
		for (int i = 0; i < raw.length(); i++)
		{
			char c = raw.charAt(i);
			// isWhitespace misses U+00A0 and isSpaceChar misses \t and \n, so both are needed.
			// FORMAT covers the zero-width family and the BOM.
			if (Character.isWhitespace(c) || Character.isSpaceChar(c)
				|| Character.getType(c) == Character.FORMAT || Character.isISOControl(c))
			{
				continue;
			}
			cleaned.append(c);
		}
		return cleaned.toString();
	}

	/** Sanitized with trailing slashes dropped, or "" if OkHttp cannot build a request on it. */
	public static String normalizeBaseUrl(String raw)
	{
		String cleaned = sanitize(raw).replaceAll("/+$", "");
		if (cleaned.isEmpty())
		{
			return "";
		}
		return HttpUrl.parse(cleaned) != null ? cleaned : "";
	}

	public static String bearer(String rawToken)
	{
		return "Bearer " + sanitize(rawToken);
	}
}

package com.fauxbingo.services;

import com.fauxbingo.services.data.Confidence;
import com.fauxbingo.services.data.DetectionMethod;
import com.fauxbingo.services.data.DropItem;
import com.fauxbingo.services.data.DropSignal;
import com.fauxbingo.services.data.DropType;
import com.fauxbingo.services.data.MergedDropEvent;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.UUID;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.LongSupplier;
import java.util.function.Predicate;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Merges the one signal each loot handler produces into a single authoritative/enriched event
 * per physical drop, so EventEnvelopeSink (EventsApiService) only ever sees one event for one
 * item.
 *
 * Two dedup layers exist on purpose. LootEventHandler's TILE_SCAN/SERVER pairing and
 * RaidLootHandler's own chat+chest assembly already solve same-method duplicates with timing
 * this service can't match (raid chat-to-chest latency can exceed the window below). This
 * service only handles the cross-method case: the same item reported via more than one
 * detection method.
 *
 * Chambers of Xeric is the exception to the fixed window: its chat lines land when Olm dies, and
 * the chest can be opened any amount of time after. While the player is inside the raid,
 * RaidLootHandler has groups of nothing but chat lines held open until something authoritative
 * joins them or the player leaves. Anything with an EXACT signal (the raid's own kills, the chest
 * once it opens) keeps the normal window, since the API stamps an event when it's sent.
 */
@Slf4j
@Singleton
public class DropCorrelationService
{
	private static final long CORRELATION_WINDOW_MS = 5_000;
	private static final long SWEEP_INTERVAL_MS = 500;
	/** Backstop for a hold whose release never arrives, so loot can't be trapped indefinitely. */
	private static final long MAX_HOLD_MS = 60 * 60_000;
	private static final Pattern QUANTITY_PREFIX = Pattern.compile("^[0-9,]+\\s*x\\s+");

	private final EventEnvelopeSink envelopeSink;
	private final ScheduledExecutorService executor;

	private final Deque<PendingGroup> pendingGroups = new ArrayDeque<>();
	private ScheduledFuture<?> sweepTask;
	private boolean holding = false;

	/** Swapped out by tests so windows can elapse without sleeping. */
	LongSupplier clock = System::currentTimeMillis;

	@Inject
	public DropCorrelationService(EventEnvelopeSink envelopeSink, ScheduledExecutorService executor)
	{
		this.envelopeSink = envelopeSink;
		this.executor = executor;
	}

	public void start()
	{
		if (sweepTask != null && !sweepTask.isCancelled())
		{
			return;
		}
		sweepTask = executor.scheduleAtFixedRate(this::sweep, SWEEP_INTERVAL_MS, SWEEP_INTERVAL_MS, TimeUnit.MILLISECONDS);
	}

	public void shutdown()
	{
		if (sweepTask != null)
		{
			sweepTask.cancel(false);
			sweepTask = null;
		}
		flushAll();
	}

	/** Handlers call this instead of touching EventsApiService directly. */
	public synchronized void report(DropSignal signal)
	{
		if (signal == null)
		{
			return;
		}

		boolean exact = signal.getDetectionMethod().getConfidence() == Confidence.EXACT;
		long now = clock.getAsLong();

		PendingGroup group = findMatchingGroup(signal);
		if (group == null)
		{
			boolean hold = holding && !exact;
			group = new PendingGroup(now + (hold ? MAX_HOLD_MS : CORRELATION_WINDOW_MS));
			group.held = hold;
			pendingGroups.add(group);
		}
		else if (group.held && exact)
		{
			group.held = false;
			group.deadline = now + CORRELATION_WINDOW_MS;
		}
		group.signals.add(signal);
	}

	/**
	 * Chat-only groups opened from now on stay pending until an EXACT signal joins them or
	 * releaseHeldGroups, not just for the window.
	 */
	public synchronized void holdNewGroups()
	{
		holding = true;
	}

	/**
	 * Gives every held group a normal window from now rather than dispatching it on the spot, so
	 * a signal still waiting on its screenshot can join.
	 */
	public synchronized void releaseHeldGroups()
	{
		holding = false;
		long deadline = clock.getAsLong() + CORRELATION_WINDOW_MS;
		for (PendingGroup group : pendingGroups)
		{
			if (group.held)
			{
				group.held = false;
				group.deadline = Math.min(group.deadline, deadline);
			}
		}
	}

	/**
	 * Item-name/id intersection is the normal match, gated on quantity: a raid rolls its normal
	 * reward table several times, so one chest of 110 Vials of blood arrives in chat as separate
	 * "50 x" and "60 x" valuable drops that all belong to it.
	 *
	 * PET signals carry no item identity at all (the game's pet message never names it), so they
	 * pair against the nearest unclaimed COLLECTION_LOG signal instead - the only way the plugin
	 * ever learns a pet's name. That pairing works regardless of which signal lands first.
	 */
	private PendingGroup findMatchingGroup(DropSignal signal)
	{
		boolean isPet = signal.getDetectionMethod().getType() == DropType.PET;
		boolean isCollectionLog = signal.getDetectionMethod().getType() == DropType.COLLECTION_LOG;

		if (isPet)
		{
			return findGroup(g -> g.hasCollectionLog() && !g.hasPet());
		}

		if (signal.getDetectionMethod().getConfidence() == Confidence.EXACT)
		{
			PendingGroup counterpart = findGroup(g -> g.hasCounterpartOf(signal));
			if (counterpart != null)
			{
				return counterpart;
			}
		}

		Map<String, Integer> quantities = itemQuantities(signal);
		if (!quantities.isEmpty())
		{
			PendingGroup byItem = signal.getDetectionMethod().getConfidence() == Confidence.EXACT
				? absorbMatchingGroups(signal, quantities)
				: findGroupWithRoom(signal.getDetectionMethod(), quantities);
			if (byItem != null)
			{
				return byItem;
			}
		}

		if (isCollectionLog)
		{
			return findGroup(g -> g.hasPet() && !g.hasCollectionLog());
		}

		return null;
	}

	/**
	 * A DERIVED signal needs a count to fit inside: the EXACT one when the group has it, otherwise
	 * what the group's other chat methods already claimed. So a collection-log line joins the
	 * valuable-drop line for the same unique ahead of the kill's loot event, instead of being left
	 * behind in its own group when that loot event absorbs the valuable drop. Two lines from one
	 * method are still two drops until something authoritative says otherwise.
	 */
	private PendingGroup findGroupWithRoom(DetectionMethod method, Map<String, Integer> quantities)
	{
		for (PendingGroup group : pendingGroups)
		{
			Set<String> groupKeys = group.itemKeys();
			boolean shared = false;
			boolean fits = true;

			for (Map.Entry<String, Integer> entry : quantities.entrySet())
			{
				if (!groupKeys.contains(entry.getKey()))
				{
					continue;
				}
				shared = true;

				int capacity = group.capacityFor(entry.getKey());
				if (capacity <= 0)
				{
					capacity = group.derivedDemand(entry.getKey());
				}
				if (capacity <= 0 || group.claimedFor(entry.getKey(), method) + entry.getValue() > capacity)
				{
					fits = false;
					break;
				}
			}

			if (shared && fits)
			{
				return group;
			}
		}
		return null;
	}

	/**
	 * Claims every group this signal's items cover, not just the first: a chest arrives after
	 * several chat lines that each became their own group. Stops folding groups in once they
	 * exhaust the count for an item, so an unrelated drop of it isn't swallowed too.
	 *
	 * Only a group still holding a DERIVED signal is eligible. Two EXACT signals are two separate
	 * drops and folding them together loses one: resolve() keeps a single primary, and
	 * EventsApiService builds the payload from that primary's items alone. Repeated kills of one
	 * NPC inside the window all share its common drop, which is why a cannon collapsed a whole
	 * window into its first kill.
	 */
	private PendingGroup absorbMatchingGroups(DropSignal signal, Map<String, Integer> quantities)
	{
		Map<String, Integer> remaining = new HashMap<>(quantities);
		List<PendingGroup> absorbed = new ArrayList<>();

		for (PendingGroup group : pendingGroups)
		{
			if (!group.hasDerived() || !group.acceptsExactFrom(signal))
			{
				continue;
			}

			Set<String> shared = new HashSet<>(group.itemKeys());
			shared.retainAll(remaining.keySet());
			if (shared.isEmpty())
			{
				continue;
			}

			boolean fits = true;
			for (String key : shared)
			{
				if (group.derivedDemand(key) > remaining.get(key))
				{
					fits = false;
					break;
				}
			}
			if (!fits)
			{
				continue;
			}

			for (String key : shared)
			{
				remaining.put(key, remaining.get(key) - group.derivedDemand(key));
			}
			absorbed.add(group);
		}

		if (absorbed.isEmpty())
		{
			return null;
		}

		PendingGroup host = absorbed.get(0);
		for (PendingGroup other : absorbed.subList(1, absorbed.size()))
		{
			host.signals.addAll(other.signals);
			pendingGroups.remove(other);
		}
		return host;
	}

	private PendingGroup findGroup(Predicate<PendingGroup> predicate)
	{
		for (PendingGroup group : pendingGroups)
		{
			if (predicate.test(group))
			{
				return group;
			}
		}
		return null;
	}

	/** Item key to the count this signal reports for it. */
	private static Map<String, Integer> itemQuantities(DropSignal signal)
	{
		Map<String, Integer> quantities = new HashMap<>();
		if (signal.getItems() == null)
		{
			return quantities;
		}
		for (DropItem item : signal.getItems())
		{
			int quantity = Math.max(item.getQuantity(), 0);
			if (item.getId() != null)
			{
				quantities.merge("id:" + item.getId(), quantity, Integer::sum);
			}
			String normalized = normalizeName(item.getName());
			if (normalized != null)
			{
				quantities.merge("name:" + normalized, quantity, Integer::sum);
			}
		}
		return quantities;
	}

	/**
	 * npcId when both signals carry one, source name otherwise. Either being absent counts as a
	 * match rather than blocking one: ServerNpcLoot can arrive with a null composition name, and
	 * chest and loot-tracker-event signals never carry an npcId.
	 */
	private static boolean sameSource(DropSignal a, DropSignal b)
	{
		if (a.getNpcId() != null && b.getNpcId() != null)
		{
			return a.getNpcId().equals(b.getNpcId());
		}

		String first = a.getSourceName();
		String second = b.getSourceName();
		return first == null || second == null || first.equalsIgnoreCase(second);
	}

	/**
	 * RaidLootHandler and the Loot Tracker both read the raid chest's container when it opens, so
	 * they are two views of one chest rather than two drops. The two EXACT signals would otherwise
	 * only meet if a chat line for the chest was still pending to bridge them.
	 *
	 * Source names are compared by prefix because the Loot Tracker never names the mode
	 * ("Chambers of Xeric" for a Challenge Mode chest too). The tracker's list is allowed to fall
	 * short of the chest's, since LootEventHandler subtracts anything unequipped on the same tick.
	 */
	private static boolean sameChest(DropSignal a, DropSignal b)
	{
		DropSignal chest;
		DropSignal tracker;
		if (a.getDetectionMethod() == DetectionMethod.RAID_CHEST_CONTAINER
			&& b.getDetectionMethod() == DetectionMethod.LOOT_TRACKER_EVENT)
		{
			chest = a;
			tracker = b;
		}
		else if (b.getDetectionMethod() == DetectionMethod.RAID_CHEST_CONTAINER
			&& a.getDetectionMethod() == DetectionMethod.LOOT_TRACKER_EVENT)
		{
			chest = b;
			tracker = a;
		}
		else
		{
			return false;
		}

		String chestName = chest.getSourceName();
		String trackerName = tracker.getSourceName();
		if (chestName == null || trackerName == null
			|| !chestName.regionMatches(true, 0, trackerName, 0, trackerName.length()))
		{
			return false;
		}

		Map<Integer, Integer> chestItems = itemIdTotals(chest);
		Map<Integer, Integer> trackerItems = itemIdTotals(tracker);
		if (trackerItems.isEmpty())
		{
			return false;
		}
		for (Map.Entry<Integer, Integer> entry : trackerItems.entrySet())
		{
			if (chestItems.getOrDefault(entry.getKey(), 0) < entry.getValue())
			{
				return false;
			}
		}
		return true;
	}

	private static Map<Integer, Integer> itemIdTotals(DropSignal signal)
	{
		Map<Integer, Integer> totals = new HashMap<>();
		if (signal.getItems() == null)
		{
			return totals;
		}
		for (DropItem item : signal.getItems())
		{
			if (item.getId() != null)
			{
				totals.merge(item.getId(), Math.max(item.getQuantity(), 0), Integer::sum);
			}
		}
		return totals;
	}

	/** Strips a chat-embedded quantity prefix like "30 x " so names line up across handlers. */
	private static String normalizeName(String name)
	{
		if (name == null)
		{
			return null;
		}
		String stripped = QUANTITY_PREFIX.matcher(name.trim()).replaceFirst("");
		return stripped.toLowerCase(Locale.ROOT);
	}

	private synchronized void sweep()
	{
		long now = clock.getAsLong();
		Iterator<PendingGroup> it = pendingGroups.iterator();
		while (it.hasNext())
		{
			PendingGroup group = it.next();
			if (now >= group.deadline)
			{
				it.remove();
				resolveAndDispatch(group);
			}
		}
	}

	/** Called from shutdown so nothing lingers unresolved past a logout/plugin stop. */
	private synchronized void flushAll()
	{
		Iterator<PendingGroup> it = pendingGroups.iterator();
		while (it.hasNext())
		{
			PendingGroup group = it.next();
			it.remove();
			resolveAndDispatch(group);
		}
	}

	private void resolveAndDispatch(PendingGroup group)
	{
		if (group.signals.isEmpty())
		{
			return;
		}

		try
		{
			MergedDropEvent merged = resolve(group.signals, group.dropGroupId);
			dispatch(merged);
		}
		catch (Exception e)
		{
			log.error("Error resolving correlated drop", e);
		}
	}

	private MergedDropEvent resolve(List<DropSignal> signals, String dropGroupId)
	{
		DropSignal primary = pickPrimary(signals);

		DropSignal petSignal = findFirst(signals, s -> s.getDetectionMethod().getType() == DropType.PET);
		DropSignal clogSignal = findFirst(signals, s -> s.getDetectionMethod().getType() == DropType.COLLECTION_LOG);

		String petName = null;
		String sourceNameGuess = petSignal != null ? petSignal.getSourceNameGuess() : null;
		if (petSignal != null && clogSignal != null && clogSignal.getItems() != null && !clogSignal.getItems().isEmpty())
		{
			petName = clogSignal.getItems().get(0).getName();
		}

		// A capture can fail per signal, so fall back rather than let the primary's miss decide it.
		DropSignal withScreenshot = primary.getScreenshot() != null
			? primary
			: findFirst(signals, s -> s.getScreenshot() != null);

		Long corroboratedValue = null;
		if (primary.getTotalValueGe() == null || primary.getTotalValueGe() == 0)
		{
			for (DropSignal other : signals)
			{
				if (other != primary && other.getTotalValueGe() != null && other.getTotalValueGe() > 0)
				{
					corroboratedValue = other.getTotalValueGe();
					break;
				}
			}
		}

		return MergedDropEvent.builder()
			.type(primary.getDetectionMethod().getType())
			.dropGroupId(dropGroupId)
			.primarySignal(primary)
			.contributingSignals(new ArrayList<>(signals))
			.petName(petName)
			.sourceNameGuess(sourceNameGuess)
			.corroboratedValueGe(corroboratedValue)
			.screenshot(withScreenshot != null ? withScreenshot.getScreenshot() : null)
			.build();
	}

	private static DropSignal findFirst(List<DropSignal> signals, Predicate<DropSignal> predicate)
	{
		for (DropSignal signal : signals)
		{
			if (predicate.test(signal))
			{
				return signal;
			}
		}
		return null;
	}

	/** EXACT beats DERIVED; among ties, richer data (has an itemId) wins; final tiebreak is arrival order. */
	private static DropSignal pickPrimary(List<DropSignal> signals)
	{
		DropSignal best = null;
		int bestScore = Integer.MIN_VALUE;
		for (DropSignal signal : signals)
		{
			int score = score(signal);
			if (score > bestScore)
			{
				bestScore = score;
				best = signal;
			}
		}
		return best;
	}

	private static int score(DropSignal signal)
	{
		int score = 0;
		if (signal.getDetectionMethod().getConfidence() == Confidence.EXACT)
		{
			score += 10;
		}
		if (signal.getItems() != null && signal.getItems().stream().anyMatch(i -> i.getId() != null))
		{
			score += 1;
		}
		return score;
	}

	/** Only remaining consumer is the sink, everything reaches the API regardless of value. */
	private void dispatch(MergedDropEvent merged)
	{
		envelopeSink.accept(merged);
	}

	private static class PendingGroup
	{
		private long deadline;
		/** Chat lines only, opened inside Chambers of Xeric; only MAX_HOLD_MS closes it until released. */
		private boolean held;
		private final String dropGroupId = UUID.randomUUID().toString();
		private final List<DropSignal> signals = new ArrayList<>();

		PendingGroup(long deadline)
		{
			this.deadline = deadline;
		}

		boolean hasPet()
		{
			return signals.stream().anyMatch(s -> s.getDetectionMethod().getType() == DropType.PET);
		}

		boolean hasCollectionLog()
		{
			return signals.stream().anyMatch(s -> s.getDetectionMethod().getType() == DropType.COLLECTION_LOG);
		}

		/** Already holds the other view of the chest this signal reports, and not this view yet. */
		boolean hasCounterpartOf(DropSignal signal)
		{
			boolean counterpart = false;
			for (DropSignal existing : signals)
			{
				if (existing.getDetectionMethod() == signal.getDetectionMethod())
				{
					return false;
				}
				counterpart |= sameChest(existing, signal);
			}
			return counterpart;
		}

		boolean hasDerived()
		{
			return signals.stream().anyMatch(s -> s.getDetectionMethod().getConfidence() != Confidence.EXACT);
		}

		/**
		 * A group anchored by one source's EXACT signal is closed to every other source. Without
		 * this, a chat line sitting between two kills gives them a shared item key, and the second
		 * kill absorbs the first kill's group through it.
		 */
		boolean acceptsExactFrom(DropSignal signal)
		{
			for (DropSignal existing : signals)
			{
				if (existing.getDetectionMethod().getConfidence() == Confidence.EXACT
					&& !sameSource(existing, signal))
				{
					return false;
				}
			}
			return true;
		}

		Set<String> itemKeys()
		{
			Set<String> keys = new HashSet<>();
			for (DropSignal signal : signals)
			{
				keys.addAll(itemQuantities(signal).keySet());
			}
			return keys;
		}

		/** The authoritative count DERIVED signals slot into. Zero if no EXACT signal covers the item. */
		int capacityFor(String key)
		{
			int capacity = 0;
			for (DropSignal signal : signals)
			{
				if (signal.getDetectionMethod().getConfidence() != Confidence.EXACT)
				{
					continue;
				}
				Integer quantity = itemQuantities(signal).get(key);
				if (quantity != null)
				{
					capacity = Math.max(capacity, quantity);
				}
			}
			return capacity;
		}

		/** How much of an item's capacity one detection method has already taken. */
		int claimedFor(String key, DetectionMethod method)
		{
			int claimed = 0;
			for (DropSignal signal : signals)
			{
				if (signal.getDetectionMethod() != method)
				{
					continue;
				}
				Integer quantity = itemQuantities(signal).get(key);
				if (quantity != null)
				{
					claimed += quantity;
				}
			}
			return claimed;
		}

		/**
		 * Methods are compared rather than summed: a collection-log line and a valuable-drop line
		 * describe the same item, while two valuable-drop lines are two separate rolls.
		 */
		int derivedDemand(String key)
		{
			Set<DetectionMethod> methods = EnumSet.noneOf(DetectionMethod.class);
			for (DropSignal signal : signals)
			{
				if (signal.getDetectionMethod().getConfidence() != Confidence.EXACT)
				{
					methods.add(signal.getDetectionMethod());
				}
			}

			int demand = 0;
			for (DetectionMethod method : methods)
			{
				demand = Math.max(demand, claimedFor(key, method));
			}
			return demand;
		}
	}
}

package com.fauxbingo.services;

import com.fauxbingo.services.data.MergedDropEvent;

/**
 * Receives the one merged/authoritative event per physical drop, resolved by
 * DropCorrelationService. EventsApiService implements this and posts to the v1 events endpoint;
 * the seam keeps the correlation engine from needing to know about HTTP transport at all.
 */
public interface EventEnvelopeSink
{
	void accept(MergedDropEvent event);
}

package com.fauxbingo.services;

import com.fauxbingo.FauxBingoConfig;
