/**
 * POST /v1/events client. This is the real seam behind EventEnvelopeSink: DropCorrelationService
 * hands it one MergedDropEvent per physical drop (LOOT/COLLECTION_LOG/PET), sent immediately as
 * a batch of one; DeathHandler calls submitDeath directly, batched on a 5s/50-event timer per
 * the contract. Delivery is in-memory only - a failed batch retries with backoff, but nothing
 * survives a plugin restart or logout.
 *
 * The events endpoint is fire and forget: it answers 2xx (published) or 5xx (retry this batch)
 * and never carries a per-event verdict, so there's nothing to wait on before uploading evidence.
 * eventId is generated here, client-side, before the envelope is even built, so a captured
 * screenshot uploads immediately in parallel with the batch send rather than waiting on its
 * response. That upload retries on its own ladder - it is the only copy of an image nobody can
 * retake, and the event it belongs to has already landed without it.
 */
@Slf4j
@Singleton
public class EventsApiService implements EventEnvelopeSink
{
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	private static final MediaType JPEG = MediaType.parse("image/jpeg");
	private static final String EVENTS_PATH = "/v1/events";
	private static final String SCREENSHOT_PATH_SUFFIX = "/screenshot";
	private static final int SCHEMA_VERSION = 1;
	private static final long INITIAL_RETRY_DELAY_MS = 1_000;
	private static final long MAX_RETRY_DELAY_MS = 60_000;
	private static final long DEATH_BATCH_FLUSH_MS = 5_000;
	private static final int DEATH_BATCH_MAX_SIZE = 50;

	// The server caps an upload at 5MB and re-encodes anything larger than 2560x1440 down to it,
	// so sending more than this is bytes the site was going to throw away - paid for on the
	// player's upstream, where a 4K or HiDPI client's lossless PNG was blowing the cap outright.
	private static final int MAX_SCREENSHOT_WIDTH = 2560;
	private static final int MAX_SCREENSHOT_HEIGHT = 1440;
	private static final int MAX_SCREENSHOT_BYTES = 5 * 1024 * 1024;
	private static final float[] SCREENSHOT_QUALITY = {0.85f, 0.65f, 0.45f};
	private static final int SCREENSHOT_MAX_ATTEMPTS = 6;

	private final Client client;
	private final FauxBingoConfig config;
	private final Provider<String> apiBaseUrl;
	private final OkHttpClient okHttpClient;
	private final Gson gson;
	private final ScheduledExecutorService executor;

	private final AtomicInteger sequence = new AtomicInteger(0);
	private final List<EventEnvelopeDto> deathQueue = new ArrayList<>();
	private volatile long deathQueueOpenedAtMs = 0;
	private volatile ActorDto currentActor = null;

	private ScheduledFuture<?> deathFlushTask = null;

	@Inject
	public EventsApiService(Client client, FauxBingoConfig config,
		@Named(FauxBingoPlugin.API_BASE_URL_KEY) Provider<String> apiBaseUrl, OkHttpClient okHttpClient,
		Gson gson, ScheduledExecutorService executor)
	{
		this.client = client;
		this.config = config;
		this.apiBaseUrl = apiBaseUrl;
		this.okHttpClient = okHttpClient;
		this.gson = gson;
		this.executor = executor;
	}

	public void start()
	{
		if (deathFlushTask == null || deathFlushTask.isCancelled())
		{
			// scheduleAtFixedRate stops rescheduling for good if a task throws, and logs nothing.
			deathFlushTask = executor.scheduleAtFixedRate(() -> {
				try
				{
					flushDeathQueueIfDue();
				}
				catch (Exception e)
				{
					log.warn("Death queue flush failed; keeping the schedule alive", e);
				}
			}, 1, 1, TimeUnit.SECONDS);
		}
	}

	public void shutdown()
	{
		if (deathFlushTask != null)
		{
			deathFlushTask.cancel(false);
			deathFlushTask = null;
		}
		flushDeathQueueNow();
	}

	/** New login/username change: sequence starts back at 0 and the cached actor is dropped. */
	public void resetSession()
	{
		sequence.set(0);
		currentActor = null;
	}

	@Override
	public void accept(MergedDropEvent merged)
	{
		if (!enabled() || merged == null || merged.getPrimarySignal() == null)
		{
			return;
		}

		ActorDto actor = currentActor;
		if (actor == null)
		{
			return;
		}

		Object payload = buildPayload(merged);
		if (payload == null)
		{
			log.debug("No payload builder for merged drop type {}, dropping", merged.getType());
			return;
		}

		DropSignal primary = merged.getPrimarySignal();
		String eventId = UUID.randomUUID().toString();
		EventEnvelopeDto envelope = EventEnvelopeDto.builder()
			.eventId(eventId)
			.schemaVersion(SCHEMA_VERSION)
			.pluginVersion(PluginVersion.VERSION)
			.occurredAt(Instant.now().toString())
			.sequence(sequence.getAndIncrement())
			.replay(false)
			.dropGroupId(merged.getDropGroupId())
			.actor(actor)
			.type(merged.getType().name())
			.detection(DetectionDto.builder()
				.method(primary.getDetectionMethod().name())
				.confidence(primary.getDetectionMethod().getConfidence().name())
				.raw(primary.getRaw())
				.build())
			.payload(payload)
			.screenshot(ScreenshotFlagDto.builder().captured(merged.getScreenshot() != null).build())
			.build();

		if (merged.getScreenshot() != null)
		{
			// No verdict to wait on and eventId is already ours, so this races ahead of (and
			// independent of) the batch send below. The mediator tolerates that (docs/bingo-events-api.md §11).
			uploadScreenshot(eventId, merged.getScreenshot());
		}

		// LOOT/COLLECTION_LOG/PET post immediately, typically a batch of one, per the contract's
		// "Immediate" delivery path.
		sendBatch(Collections.singletonList(envelope), INITIAL_RETRY_DELAY_MS);
	}

	/** DEATH is the "Batched" path: flushed on a 5s timer or at 50 events, whichever first. */
	public void submitDeath(DeathSignal signal)
	{
		if (!enabled() || signal == null)
		{
			return;
		}

		ActorDto actor = currentActor;
		if (actor == null)
		{
			return;
		}

		DeathPayloadDto payload = DeathPayloadDto.builder()
			.regionId(signal.getRegionId())
			.killerName(signal.getKillerName())
			.killerKind(signal.getKillerKind())
			.build();

		EventEnvelopeDto envelope = EventEnvelopeDto.builder()
			.eventId(UUID.randomUUID().toString())
			.schemaVersion(SCHEMA_VERSION)
			.pluginVersion(PluginVersion.VERSION)
			.occurredAt(Instant.now().toString())
			.sequence(sequence.getAndIncrement())
			.replay(false)
			.actor(actor)
			.type("DEATH")
			.detection(DetectionDto.builder().method("ACTOR_DEATH").confidence("EXACT").build())
			.payload(payload)
			.screenshot(ScreenshotFlagDto.builder().captured(false).build())
			.build();

		synchronized (deathQueue)
		{
			if (deathQueue.isEmpty())
			{
				deathQueueOpenedAtMs = System.currentTimeMillis();
			}
			deathQueue.add(envelope);
			if (deathQueue.size() < DEATH_BATCH_MAX_SIZE)
			{
				return;
			}
		}
		flushDeathQueueNow();
	}

	private void flushDeathQueueIfDue()
	{
		boolean due;
		synchronized (deathQueue)
		{
			due = !deathQueue.isEmpty() && System.currentTimeMillis() - deathQueueOpenedAtMs >= DEATH_BATCH_FLUSH_MS;
		}
		if (due)
		{
			flushDeathQueueNow();
		}
	}

	private void flushDeathQueueNow()
	{
		List<EventEnvelopeDto> batch;
		synchronized (deathQueue)
		{
			if (deathQueue.isEmpty())
			{
				return;
			}
			batch = new ArrayList<>(deathQueue);
			deathQueue.clear();
		}
		sendBatch(batch, INITIAL_RETRY_DELAY_MS);
	}

	private Object buildPayload(MergedDropEvent merged)
	{
		DropSignal primary = merged.getPrimarySignal();
		switch (merged.getType())
		{
			case LOOT:
				return buildLootPayload(primary, merged);
			case COLLECTION_LOG:
				return buildCollectionLogPayload(primary);
			case PET:
				return PetPayloadDto.builder()
					.petName(merged.getPetName())
					.sourceName(merged.getSourceNameGuess())
					.build();
			default:
				return null;
		}
	}

	private LootPayloadDto buildLootPayload(DropSignal primary, MergedDropEvent merged)
	{
		LocationDto location = primary.getRegionId() != null
			? LocationDto.builder().regionId(primary.getRegionId()).plane(primary.getPlane()).build()
			: null;

		LootSourceDto source = LootSourceDto.builder()
			.kind(primary.getSourceKind() != null ? primary.getSourceKind().name() : "OTHER")
			.name(primary.getSourceName())
			.npcId(primary.getNpcId())
			.combatLevel(primary.getCombatLevel())
			.killCount(primary.getKillCount())
			.variant(primary.getVariant())
			.location(location)
			.build();

		List<LootItemDto> items = primary.getItems() == null ? Collections.emptyList() : primary.getItems().stream()
			.map(this::toLootItemDto)
			.collect(Collectors.toList());

		Long totalValueGe = (primary.getTotalValueGe() != null && primary.getTotalValueGe() != 0)
			? primary.getTotalValueGe()
			: merged.getCorroboratedValueGe();

		return LootPayloadDto.builder().source(source).items(items).totalValueGe(totalValueGe).build();
	}

	private LootItemDto toLootItemDto(DropItem item)
	{
		return LootItemDto.builder()
			.itemId(item.getId())
			.name(item.getName())
			.quantity(item.getQuantity())
			.unitPriceGe(item.getUnitPriceGe())
			.build();
	}

	private CollectionLogPayloadDto buildCollectionLogPayload(DropSignal primary)
	{
		DropItem item = primary.getItems() != null && !primary.getItems().isEmpty() ? primary.getItems().get(0) : null;
		return CollectionLogPayloadDto.builder()
			.entryName(item != null ? item.getName() : null)
			.itemId(item != null ? item.getId() : null)
			.build();
	}

	/**
	 * The actor block is read straight off the client, and getAccountType() reads a varbit under
	 * the hood, which asserts client-thread-only. Dispatch (sweep/flush) runs on the executor
	 * thread, so it never reads the client at all - it reads this snapshot, taken once per
	 * session from checkLogin, which is the point where the local player is known to be loaded.
	 */
	public void onLogin(String displayName)
	{
		currentActor = ActorDto.builder()
			.accountHash(String.valueOf(client.getAccountHash()))
			.displayName(displayName)
			.accountType(client.getAccountType() != null ? client.getAccountType().name() : "UNKNOWN")
			.world(client.getWorld())
			.worldTypes(worldTypes())
			.build();
	}

	/**
	 * A hop moves world/worldTypes without ever going back through login, so the snapshot would
	 * otherwise report the old world for the rest of the session. Only those two fields can have
	 * changed, and both are readable here without the local player, which a hop has not
	 * necessarily respawned yet. Rebuilt rather than mutated in place, since the dispatch thread
	 * can be reading the current snapshot.
	 */
	public void onWorldChanged()
	{
		ActorDto cached = currentActor;
		if (cached == null)
		{
			return;
		}

		currentActor = ActorDto.builder()
			.accountHash(cached.getAccountHash())
			.displayName(cached.getDisplayName())
			.accountType(cached.getAccountType())
			.world(client.getWorld())
			.worldTypes(worldTypes())
			.build();
	}

	private List<String> worldTypes()
	{
		return client.getWorldType().stream().map(WorldType::name).collect(Collectors.toList());
	}

	private void sendBatch(List<EventEnvelopeDto> envelopes, long nextRetryDelayMs)
	{
		if (envelopes.isEmpty() || !enabled())
		{
			return;
		}

		String json = gson.toJson(envelopes);
		Request request;
		try
		{
			request = new Request.Builder()
				.url(apiBaseUrl.get() + EVENTS_PATH)
				.header("Authorization", ApiConfigSanitizer.bearer(config.apiToken()))
				.post(RequestBody.create(JSON, json))
				.build();
		}
		catch (RuntimeException e)
		{
			// Not retrying: a malformed token or URL will not fix itself on a timer.
			log.warn("Could not build the /v1/events request, dropping batch of {}; check the API token "
				+ "and base URL: {}", envelopes.size(), e.getMessage());
			return;
		}

		okHttpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("POST /v1/events failed: {}, retrying in {}ms", e.getMessage(), nextRetryDelayMs);
				scheduleRetry(envelopes, nextRetryDelayMs);
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException
			{
				try
				{
					int code = response.code();
					if (code == 401)
					{
						log.warn("POST /v1/events returned 401, token is missing or unknown. Dropping batch of {}.", envelopes.size());
						return;
					}
					if (code >= 500)
					{
						log.debug("POST /v1/events returned {}, retrying in {}ms", code, nextRetryDelayMs);
						scheduleRetry(envelopes, nextRetryDelayMs);
						return;
					}
					if (!response.isSuccessful())
					{
						log.warn("POST /v1/events returned {}: {}. Dropping batch of {}.", code, response.message(), envelopes.size());
						return;
					}

					// 2xx (204, no body) means the topic took the batch. Nothing else to read.
				}
				finally
				{
					response.close();
				}
			}
		});
	}

	private void scheduleRetry(List<EventEnvelopeDto> envelopes, long delayMs)
	{
		executor.schedule(() -> sendBatch(envelopes, Math.min(MAX_RETRY_DELAY_MS, delayMs * 2)), delayMs, TimeUnit.MILLISECONDS);
	}

	private void uploadScreenshot(String eventId, BufferedImage image)
	{
		byte[] bytes = encodeScreenshot(image);
		if (bytes != null)
		{
			sendScreenshot(eventId, bytes, INITIAL_RETRY_DELAY_MS, 1);
		}
	}

	private void sendScreenshot(String eventId, byte[] bytes, long nextRetryDelayMs, int attempt)
	{
		if (!enabled())
		{
			return;
		}

		HttpUrl url = HttpUrl.parse(apiBaseUrl.get() + EVENTS_PATH + "/" + eventId + SCREENSHOT_PATH_SUFFIX);
		if (url == null)
		{
			return;
		}

		MultipartBody multipart = new MultipartBody.Builder()
			.setType(MultipartBody.FORM)
			.addFormDataPart("file", "screenshot.jpg", RequestBody.create(JPEG, bytes))
			.build();

		Request request;
		try
		{
			request = new Request.Builder()
				.url(url)
				.header("Authorization", ApiConfigSanitizer.bearer(config.apiToken()))
				.post(multipart)
				.build();
		}
		catch (RuntimeException e)
		{
			log.warn("Could not build the screenshot upload request for event {}: {}", eventId, e.getMessage());
			return;
		}

		okHttpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				retryScreenshot(eventId, bytes, nextRetryDelayMs, attempt, e.getMessage());
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try
				{
					int code = response.code();
					if (code >= 500)
					{
						retryScreenshot(eventId, bytes, nextRetryDelayMs, attempt, "HTTP " + code);
					}
					else if (!response.isSuccessful())
					{
						log.warn("Screenshot upload for {} returned {}: {}. Dropping it.", eventId, code, response.message());
					}
				}
				finally
				{
					response.close();
				}
			}
		});
	}

	/**
	 * Bounded, unlike the event batch's retry: this holds the encoded image until it succeeds, and
	 * a client that stays offline through a raid would otherwise accumulate every capture.
	 */
	private void retryScreenshot(String eventId, byte[] bytes, long delayMs, int attempt, String cause)
	{
		if (attempt >= SCREENSHOT_MAX_ATTEMPTS)
		{
			log.warn("Screenshot upload for {} failed {} times ({}), giving up.", eventId, attempt, cause);
			return;
		}
		log.debug("Screenshot upload for {} failed ({}), retrying in {}ms", eventId, cause, delayMs);
		executor.schedule(() -> sendScreenshot(eventId, bytes, Math.min(MAX_RETRY_DELAY_MS, delayMs * 2), attempt + 1),
			delayMs, TimeUnit.MILLISECONDS);
	}

	private byte[] encodeScreenshot(BufferedImage image)
	{
		BufferedImage scaled = scaleToFit(image);
		for (float quality : SCREENSHOT_QUALITY)
		{
			byte[] bytes = toJpegBytes(scaled, quality);
			if (bytes == null)
			{
				return null;
			}
			if (bytes.length <= MAX_SCREENSHOT_BYTES)
			{
				return bytes;
			}
		}
		log.warn("Screenshot still over {} bytes at the lowest quality, dropping it", MAX_SCREENSHOT_BYTES);
		return null;
	}

	private static BufferedImage scaleToFit(BufferedImage image)
	{
		double factor = Math.min(
			MAX_SCREENSHOT_WIDTH / (double) image.getWidth(),
			MAX_SCREENSHOT_HEIGHT / (double) image.getHeight());
		int width = factor < 1 ? (int) Math.round(image.getWidth() * factor) : image.getWidth();
		int height = factor < 1 ? (int) Math.round(image.getHeight() * factor) : image.getHeight();

		// Redrawn even at native size: JPEG cannot carry the alpha channel some capture paths hand
		// back, and TYPE_INT_RGB is what the writer wants.
		BufferedImage out = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
		Graphics2D graphics = out.createGraphics();
		graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		graphics.drawImage(image, 0, 0, width, height, null);
		graphics.dispose();
		return out;
	}

	private byte[] toJpegBytes(BufferedImage image, float quality)
	{
		Iterator<ImageWriter> writers = ImageIO.getImageWritersByFormatName("jpeg");
		if (!writers.hasNext())
		{
			log.warn("No JPEG writer available, dropping screenshot");
			return null;
		}

		ImageWriter writer = writers.next();
		try (ByteArrayOutputStream out = new ByteArrayOutputStream();
			ImageOutputStream stream = ImageIO.createImageOutputStream(out))
		{
			ImageWriteParam param = writer.getDefaultWriteParam();
			param.setCompressionMode(ImageWriteParam.MODE_EXPLICIT);
			param.setCompressionQuality(quality);
			writer.setOutput(stream);
			writer.write(null, new IIOImage(image, null, null), param);
			stream.flush();
			return out.toByteArray();
		}
		catch (IOException e)
		{
			log.warn("Failed to encode screenshot", e);
			return null;
		}
		finally
		{
			writer.dispose();
		}
	}

	private boolean enabled()
	{
		return config.enableBingoApi() && !ApiConfigSanitizer.sanitize(config.apiToken()).isEmpty()
			&& !apiBaseUrl.get().isEmpty();
	}
}

package com.fauxbingo.services;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ConcurrentLinkedQueue;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.events.InteractingChanged;
import net.runelite.client.eventbus.Subscribe;

/**
 * Tracks entities the player interacts with in a rolling 10-second window.
 * Used by DeathHandler for killer detection.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class InteractionTrackingService
{
	private static final long WINDOW_MS = 10_000;

	private final Client client;
	private final ConcurrentLinkedQueue<InteractionEntry> interactions = new ConcurrentLinkedQueue<>();

	@Subscribe
	public void onInteractingChanged(InteractingChanged event)
	{
		Actor local = client.getLocalPlayer();
		if (local == null || event.getSource() != local)
		{
			return;
		}
		Actor target = event.getTarget();
		if (target == null || target == local || getCombatLevel(target) <= 0)
		{
			return;
		}
		addInteraction(target);
	}

	/**
	 * Returns names of entities the player has interacted with in the last 10 seconds.
	 * Called by PetChatHandler to guess a pet's source NPC/player, since the pet chat
	 * message never names its source.
	 */
	public List<String> getRecentInteractionNames()
	{
		pruneStale();
		List<String> names = new ArrayList<>();
		for (InteractionEntry entry : interactions)
		{
			String name = entry.getActorName();
			if (name != null && !name.isEmpty())
			{
				names.add(name);
			}
		}
		return names;
	}

	/**
	 * Returns the most recent interaction target, or null.
	 * Used by DeathHandler for killer detection.
	 */
	public Actor getLastTarget()
	{
		pruneStale();
		InteractionEntry last = null;
		for (InteractionEntry entry : interactions)
		{
			if (last == null || entry.timestamp > last.timestamp)
			{
				last = entry;
			}
		}
		return last != null ? last.actor : null;
	}

	private void addInteraction(Actor actor)
	{
		long now = System.currentTimeMillis();
		interactions.add(new InteractionEntry(actor, now));
		pruneStale();
	}

	private void pruneStale()
	{
		long cutoff = System.currentTimeMillis() - WINDOW_MS;
		InteractionEntry entry;
		while ((entry = interactions.peek()) != null && entry.timestamp < cutoff)
		{
			interactions.poll();
		}
	}

	private static int getCombatLevel(Actor a)
	{
		if (a instanceof Player)
		{
			return ((Player) a).getCombatLevel();
		}
		if (a instanceof NPC)
		{
			var comp = ((NPC) a).getComposition();
			return comp != null ? comp.getCombatLevel() : 0;
		}
		return 0;
	}

	private static class InteractionEntry
	{
		private final Actor actor;
		private final long timestamp;

		InteractionEntry(Actor actor, long timestamp)
		{
			this.actor = actor;
			this.timestamp = timestamp;
		}

		String getActorName()
		{
			return actor != null ? actor.getName() : null;
		}
	}
}

package com.fauxbingo.services;

import com.fauxbingo.FauxBingoConfig;
import com.fauxbingo.FauxBingoPlugin;
import com.fauxbingo.services.data.MeResponseDto;
import com.fauxbingo.services.data.TeamDto;
import com.google.gson.Gson;
import java.awt.Color;
import java.io.IOException;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import javax.inject.Inject;
import javax.inject.Named;
import javax.inject.Provider;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

/**
 * Identity lookup for the plugin: GET /v1/me resolves the player token to a member and their
 * team (name, icon, colors). Replaces the old bingoconfig endpoint. Team name/colour are still
 * auto-applied to the overlay config, same as before; dateTimeColor has no server-side
 * equivalent and stays user-controlled.
 */
@Slf4j
@Singleton
public class MeService
{
	private static final String ME_PATH = "/v1/me";
	private static final long CACHE_WINDOW_MS = 30_000;
	private static final long INITIAL_RETRY_DELAY_MS = 1_000;
	private static final long MAX_RETRY_DELAY_MS = 60_000;
	private static final String CONFIG_GROUP = "fauxbingo";
	private static final long REFRESH_INTERVAL_MINS = 5;

	private final FauxBingoConfig config;
	private final ConfigManager configManager;
	private final Provider<String> apiBaseUrl;
	private final OkHttpClient okHttpClient;
	private final Gson gson;
	private final ScheduledExecutorService executor;

	private volatile MeResponseDto cachedMe = null;
	private volatile long lastSuccessfulFetchMs = 0;
	private ScheduledFuture<?> retryTask = null;
	private ScheduledFuture<?> refreshTask = null;
	private final AtomicBoolean retryCancelled = new AtomicBoolean(false);
	private long nextRetryDelayMs = INITIAL_RETRY_DELAY_MS;
	private String currentCharacterName = null;

	@Inject
	public MeService(FauxBingoConfig config, ConfigManager configManager,
		@Named(FauxBingoPlugin.API_BASE_URL_KEY) Provider<String> apiBaseUrl, OkHttpClient okHttpClient,
		Gson gson, ScheduledExecutorService executor)
	{
		this.config = config;
		this.configManager = configManager;
		this.apiBaseUrl = apiBaseUrl;
		this.okHttpClient = okHttpClient;
		this.gson = gson;
		this.executor = executor;
	}

	public void start()
	{
		if (refreshTask != null && !refreshTask.isCancelled())
		{
			return;
		}
		// scheduleAtFixedRate stops rescheduling for good if a task throws, and logs nothing.
		refreshTask = executor.scheduleAtFixedRate(() -> {
			try
			{
				periodicRefresh();
			}
			catch (Exception e)
			{
				log.warn("Periodic /v1/me refresh failed; keeping the schedule alive", e);
			}
		}, REFRESH_INTERVAL_MINS, REFRESH_INTERVAL_MINS, TimeUnit.MINUTES);
	}

	public void shutdown()
	{
		if (refreshTask != null)
		{
			refreshTask.cancel(false);
			refreshTask = null;
		}
		retryCancelled.set(true);
		if (retryTask != null)
		{
			retryTask.cancel(false);
			retryTask = null;
		}
	}

	/** Trigger fetch on login. Skips if within 30s of last successful call. */
	public void onLogin(String characterName)
	{
		if (!enabled() || characterName == null || characterName.isEmpty())
		{
			return;
		}

		long now = System.currentTimeMillis();
		boolean nameChanged = !characterName.equals(currentCharacterName);

		if (!nameChanged && cachedMe != null && (now - lastSuccessfulFetchMs) < CACHE_WINDOW_MS)
		{
			log.debug("Skipping /v1/me fetch, within 30s cache window");
			return;
		}

		if (!nameChanged && retryTask != null)
		{
			log.debug("/v1/me fetch already scheduled for {}", characterName);
			return;
		}

		currentCharacterName = characterName;
		if (nameChanged)
		{
			cachedMe = null;
			lastSuccessfulFetchMs = 0;
		}

		retryCancelled.set(false);
		nextRetryDelayMs = INITIAL_RETRY_DELAY_MS;
		scheduleFetch(nextRetryDelayMs);
	}

	/** Cancel retries when character logs out. */
	public void onLogout()
	{
		retryCancelled.set(true);
		if (retryTask != null)
		{
			retryTask.cancel(false);
			retryTask = null;
		}
	}

	/** Force a refetch, e.g. after the token or enableBingoApi config changes. */
	public void refresh(String characterName)
	{
		if (characterName == null || characterName.isEmpty() || !enabled())
		{
			return;
		}

		currentCharacterName = characterName;
		if (retryTask != null)
		{
			retryTask.cancel(false);
			retryTask = null;
		}
		nextRetryDelayMs = INITIAL_RETRY_DELAY_MS;
		retryCancelled.set(false);
		doFetch(true);
	}

	public MeResponseDto getCachedMe()
	{
		return cachedMe;
	}

	private boolean enabled()
	{
		return config.enableBingoApi() && !ApiConfigSanitizer.sanitize(config.apiToken()).isEmpty()
			&& !apiBaseUrl.get().isEmpty();
	}

	private void periodicRefresh()
	{
		if (!enabled() || currentCharacterName == null || currentCharacterName.isEmpty())
		{
			return;
		}

		if (retryTask != null)
		{
			retryTask.cancel(false);
			retryTask = null;
		}
		retryCancelled.set(false);
		doFetch(false);
	}

	private void scheduleFetch(long delayMs)
	{
		if (retryCancelled.get())
		{
			return;
		}

		retryTask = executor.schedule(() -> {
			if (retryCancelled.get())
			{
				return;
			}
			doFetch(true);
		}, delayMs, TimeUnit.MILLISECONDS);
	}

	private void doFetch(boolean shouldRetry)
	{
		if (!enabled())
		{
			return;
		}

		Request request;
		try
		{
			request = new Request.Builder()
				.url(apiBaseUrl.get() + ME_PATH)
				.header("Authorization", ApiConfigSanitizer.bearer(config.apiToken()))
				.get()
				.build();
		}
		catch (RuntimeException e)
		{
			// An uncaught throw here lands in the ScheduledFuture and is never logged.
			log.warn("Could not build the /v1/me request; check the API token and base URL: {}", e.getMessage());
			return;
		}

		okHttpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("/v1/me fetch failed: {}", e.getMessage());
				if (shouldRetry)
				{
					scheduleRetry();
				}
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException
			{
				try
				{
					if (response.code() == 401)
					{
						log.warn("/v1/me returned 401, token is missing or unknown. Not retrying until login/config changes.");
						return;
					}

					if (response.isSuccessful())
					{
						String body = response.body() != null ? response.body().string() : "";
						MeResponseDto parsed = gson.fromJson(body, MeResponseDto.class);
						if (parsed != null)
						{
							cachedMe = parsed;
							applyTeamOverlayConfig(parsed.getTeam());
							lastSuccessfulFetchMs = System.currentTimeMillis();
							nextRetryDelayMs = INITIAL_RETRY_DELAY_MS;
							retryTask = null;
							log.info("Fetched /v1/me for {}", currentCharacterName);
						}
						else if (shouldRetry)
						{
							scheduleRetry();
						}
					}
					else
					{
						log.debug("/v1/me returned {}: {}", response.code(), response.message());
						if (shouldRetry)
						{
							scheduleRetry();
						}
					}
				}
				finally
				{
					response.close();
				}
			}
		});
	}

	/**
	 * Auto-configures the overlay from the team's name and primary colour, same as the old
	 * bingoconfig teamConfig. dateTimeColor has no server-side equivalent and stays user-set.
	 */
	private void applyTeamOverlayConfig(TeamDto team)
	{
		if (team == null || team.getName() == null || team.getName().trim().isEmpty())
		{
			return;
		}

		Color teamNameColor = parseHexColor(team.getColors() != null ? team.getColors().getPrimaryBackground() : null);

		try
		{
			configManager.setConfiguration(CONFIG_GROUP, "displayDateTime", true);
			configManager.setConfiguration(CONFIG_GROUP, "teamName", team.getName().trim());
			if (teamNameColor != null)
			{
				configManager.setConfiguration(CONFIG_GROUP, "teamNameColor", teamNameColor);
			}
		}
		catch (Exception e)
		{
			log.info("Failed to update team overlay configuration: {}", e.getMessage());
		}
	}

	/** Validates hex string (with or without #), exactly 6 hex digits. Returns Color or null if invalid. */
	private static Color parseHexColor(String hex)
	{
		if (hex == null)
		{
			return null;
		}
		String s = hex.startsWith("#") ? hex.substring(1) : hex;
		if (s.length() != 6)
		{
			return null;
		}
		for (int i = 0; i < 6; i++)
		{
			char c = s.charAt(i);
			if (!((c >= '0' && c <= '9') || (c >= 'A' && c <= 'F') || (c >= 'a' && c <= 'f')))
			{
				return null;
			}
		}
		try
		{
			int rgb = Integer.parseInt(s, 16);
			return new Color((rgb >> 16) & 0xFF, (rgb >> 8) & 0xFF, rgb & 0xFF);
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	private void scheduleRetry()
	{
		if (retryCancelled.get())
		{
			return;
		}

		long delay = nextRetryDelayMs;
		nextRetryDelayMs = Math.min(MAX_RETRY_DELAY_MS, nextRetryDelayMs * 2);
		scheduleFetch(delay);
	}
}

package com.fauxbingo.services;

import java.io.IOException;
import java.io.InputStream;
import java.util.Properties;
import lombok.extern.slf4j.Slf4j;

/**
 * Reads the pluginVersion out of version.properties
 *
 * version.properties holds a plain, manually-bumped literal.
 * Bump the value in version.properties directly whenever a code change to the API integration
 * (envelope shape, EventsApiService, payload DTOs, etc.) warrants reporting a new version.
 */
@Slf4j
final class PluginVersion
{
	static final String VERSION = load();

	private PluginVersion()
	{
	}

	private static String load()
	{
		try (InputStream in = PluginVersion.class.getResourceAsStream("/version.properties"))
		{
			if (in == null)
			{
				return "unknown";
			}
			Properties props = new Properties();
			props.load(in);
			String version = props.getProperty("version");
			return version != null && !version.trim().isEmpty() ? version.trim() : "unknown";
		}
		catch (IOException e)
		{
			log.debug("Could not read version.properties", e);
			return "unknown";
		}
	}
}

package com.fauxbingo.services;

import com.fauxbingo.FauxBingoConfig;
import com.fauxbingo.FauxBingoPlugin;
import com.fauxbingo.services.data.SeenRequestDto;
import com.google.gson.Gson;
import java.io.IOException;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Named;
import javax.inject.Provider;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.client.callback.ClientThread;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/**
 * Presence heartbeat: POST /v1/seen every 5 minutes while actively logged in. This is how the
 * website learns about new accounts before they ever produce a drop, and how it extrapolates
 * playtime. Never called from the login screen. 5 minutes matches the server's documented
 * session-stitching cadence (docs/v1-api.md, "Presence and sessions") rather than the 5s
 * originally floated, since the server tolerates gaps up to 15 minutes anyway.
 */
@Slf4j
@Singleton
public class PresenceService
{
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	private static final String SEEN_PATH = "/v1/seen";
	private static final long HEARTBEAT_INTERVAL_MINS = 5;

	private final Client client;
	private final ClientThread clientThread;
	private final FauxBingoConfig config;
	private final Provider<String> apiBaseUrl;
	private final OkHttpClient okHttpClient;
	private final Gson gson;
	private final ScheduledExecutorService executor;

	private ScheduledFuture<?> heartbeatTask = null;

	@Inject
	public PresenceService(Client client, ClientThread clientThread, FauxBingoConfig config,
		@Named(FauxBingoPlugin.API_BASE_URL_KEY) Provider<String> apiBaseUrl, OkHttpClient okHttpClient,
		Gson gson, ScheduledExecutorService executor)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.apiBaseUrl = apiBaseUrl;
		this.okHttpClient = okHttpClient;
		this.gson = gson;
		this.executor = executor;
	}

	public void start()
	{
		if (heartbeatTask != null && !heartbeatTask.isCancelled())
		{
			return;
		}
		// scheduleAtFixedRate stops rescheduling for good if a task throws, and logs nothing.
		heartbeatTask = executor.scheduleAtFixedRate(() -> {
			try
			{
				sendIfLoggedIn();
			}
			catch (Exception e)
			{
				log.warn("Presence heartbeat failed; keeping the schedule alive", e);
			}
		}, HEARTBEAT_INTERVAL_MINS, HEARTBEAT_INTERVAL_MINS, TimeUnit.MINUTES);
	}

	public void shutdown()
	{
		if (heartbeatTask != null)
		{
			heartbeatTask.cancel(false);
			heartbeatTask = null;
		}
	}

	/** Fire one immediate heartbeat on login so a fresh account registers without waiting 5 minutes. */
	public void onLogin(String characterName)
	{
		sendIfLoggedIn();
	}

	private void sendIfLoggedIn()
	{
		if (!enabled())
		{
			return;
		}

		// The scheduled heartbeat runs on the executor thread, not the client thread, and
		// getAccountType() reads a varbit under the hood, which asserts client-thread-only.
		// invoke() runs inline if we're already on the client thread (the onLogin path).
		clientThread.invoke(() -> {
			if (client.getGameState() != GameState.LOGGED_IN)
			{
				return;
			}

			Player local = client.getLocalPlayer();
			if (local == null || local.getName() == null || local.getName().isEmpty())
			{
				return;
			}

			SeenRequestDto body = SeenRequestDto.builder()
				.accountHash(String.valueOf(client.getAccountHash()))
				.displayName(local.getName())
				.accountType(client.getAccountType() != null ? client.getAccountType().name() : "UNKNOWN")
				.build();

			send(body);
		});
	}

	private void send(SeenRequestDto body)
	{
		String json = gson.toJson(body);
		Request request;
		try
		{
			request = new Request.Builder()
				.url(apiBaseUrl.get() + SEEN_PATH)
				.header("Authorization", ApiConfigSanitizer.bearer(config.apiToken()))
				.post(RequestBody.create(JSON, json))
				.build();
		}
		catch (RuntimeException e)
		{
			log.warn("Could not build the /v1/seen request; check the API token and base URL: {}", e.getMessage());
			return;
		}

		okHttpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("POST /v1/seen failed: {}", e.getMessage());
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException
			{
				try
				{
					if (response.code() == 409)
					{
						log.warn("POST /v1/seen: account {} is already claimed by another player, not retrying.", body.getDisplayName());
					}
					else if (response.code() == 401)
					{
						log.warn("POST /v1/seen returned 401, token is missing or unknown.");
					}
					else if (!response.isSuccessful())
					{
						log.debug("POST /v1/seen returned {}: {}", response.code(), response.message());
					}
					else
					{
						log.info("POST /v1/seen ok for {}", body.getDisplayName());
					}
				}
				finally
				{
					response.close();
				}
			}
		});
	}

	private boolean enabled()
	{
		return config.enableBingoApi() && !ApiConfigSanitizer.sanitize(config.apiToken()).isEmpty()
			&& !apiBaseUrl.get().isEmpty();
	}
}

package com.fauxbingo.services;

import com.fauxbingo.FauxBingoConfig;
import java.awt.image.BufferedImage;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.ui.DrawManager;

/**
 * Centralized screenshot capture with optional chat/PM hiding for privacy.
 * Hides private messages and/or main chat (per config) before capture, then unhides after.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class ScreenshotService
{
	private static final long CAPTURE_TIMEOUT_MS = 2_000;

	private final Client client;
	private final ClientThread clientThread;
	private final DrawManager drawManager;
	private final FauxBingoConfig config;
	private final ScheduledExecutorService executor;

	/**
	 * Request a screenshot. Hides PM and/or main chat per config before capture, then unhides after.
	 * Safe to call from any thread, hide/show and frame capture run on the client thread.
	 *
	 * onImage is always called exactly once, with null if no frame arrived in time. Callers report
	 * the drop either way: DrawManager drops its whole listener queue without a word when the client
	 * cannot supply a frame, and a missing picture must not cost the event as well.
	 *
	 * @param onImage consumer for the captured image, null when the capture failed
	 */
	public void requestScreenshot(Consumer<BufferedImage> onImage)
	{
		boolean hidePm = config.screenshotHidePrivateMessages();
		boolean hideChat = config.screenshotHideChat();

		clientThread.invokeLater(() -> {
			boolean pmHidden = hideWidget(hidePm, InterfaceID.PmChat.CONTAINER);
			boolean chatHidden = hideWidget(hideChat, InterfaceID.Chatbox.CHATAREA);
			AtomicBoolean delivered = new AtomicBoolean();

			Runnable restore = () -> {
				unhideWidget(pmHidden, InterfaceID.PmChat.CONTAINER);
				unhideWidget(chatHidden, InterfaceID.Chatbox.CHATAREA);
			};

			executor.schedule(() -> {
				if (delivered.compareAndSet(false, true))
				{
					log.debug("No frame within {}ms, reporting the drop without a screenshot", CAPTURE_TIMEOUT_MS);
					restore.run();
					onImage.accept(null);
				}
			}, CAPTURE_TIMEOUT_MS, TimeUnit.MILLISECONDS);

			drawManager.requestNextFrameListener(image -> {
				if (!delivered.compareAndSet(false, true))
				{
					return;
				}
				restore.run();
				onImage.accept(image instanceof BufferedImage ? (BufferedImage) image : null);
			});
		});
	}

	/**
	 * Hide a widget if shouldHide is true. Call on client thread.
	 *
	 * @return true if the widget was hidden by this call
	 */
	private boolean hideWidget(boolean shouldHide, int componentId)
	{
		if (!shouldHide)
		{
			return false;
		}
		Widget widget = client.getWidget(componentId);
		if (widget == null || widget.isHidden())
		{
			return false;
		}
		widget.setHidden(true);
		return true;
	}

	/**
	 * Unhide a widget if we had hidden it. Must run on client thread, uses ClientThread.invoke.
	 */
	private void unhideWidget(boolean shouldUnhide, int componentId)
	{
		if (!shouldUnhide)
		{
			return;
		}
		clientThread.invoke(() -> {
			Widget widget = client.getWidget(componentId);
			if (widget != null)
			{
				widget.setHidden(false);
			}
		});
	}
}

package com.fauxbingo.services;

import com.fauxbingo.FauxBingoConfig;
import com.fauxbingo.FauxBingoPlugin;
import com.fauxbingo.services.data.TeamAccountDto;
import com.fauxbingo.services.data.TeamPlayerDto;
import com.fauxbingo.services.data.TeamRosterDto;
import com.fauxbingo.services.data.TeamsResponseDto;
import com.google.gson.Gson;
import java.awt.image.BufferedImage;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import javax.inject.Named;
import javax.inject.Provider;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.IndexedSprite;
import net.runelite.api.MessageNode;
import net.runelite.api.Player;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.OverheadTextChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.Text;
import okhttp3.CacheControl;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

/**
 * Fetches the full team roster from GET /v1/teams and badges clan chat names with their team's
 * icon. Matching is on accounts[].displayName (the RSN) - players[].memberName is a Discord
 * nickname and must never be matched against an RSN (docs/v1-api.md, GET /v1/teams).
 *
 * Icons are downloaded from GET {apiBaseUrl}/v1/teams/{teamId}/icon. Every URL this service
 * contacts is built from the user-configured API base plus a hardcoded path - no URL is ever
 * taken out of an API response.
 *
 * The same icons double as chat emoji: a team with `chatCode` of `fork` is rendered wherever
 * anyone types `:fork:`, in chat or over their head. Any player may use any team's code - unlike
 * the name badge, the code is not checked against who sent the message.
 */
@Slf4j
@Singleton
public class TeamIconService
{
	private static final String TEAMS_PATH = "/v1/teams";
	private static final String ICON_SEGMENT = "icon";
	private static final long ICON_RETRY_COOLDOWN_MS = TimeUnit.MINUTES.toMillis(30);
	private static final int MAX_CHAT_CODE_LENGTH = 16;
	// Public chat's 80-character limit already caps this near 16; the guard is for the message
	// types that have no such limit.
	private static final int MAX_REPLACEMENTS_PER_MESSAGE = 8;

	private final Client client;
	private final FauxBingoConfig config;
	private final Provider<String> apiBaseUrl;
	private final OkHttpClient okHttpClient;
	private final Gson gson;
	private final ScheduledExecutorService executor;
	private final ClientThread clientThread;

	private final Map<String, String> rsnToTeamId = new HashMap<>();     // standardized RSN -> team id
	private final Map<String, String> chatCodeToTeamId = new HashMap<>(); // normalized chat code -> team id
	private final Map<String, Integer> teamToSpriteIndex = new HashMap<>(); // team id -> mod icon array index
	private final Map<String, Long> iconFetchFailures = new HashMap<>();    // team id -> when its icon last failed to fetch or decode
	private int iconsRegisteredCount = 0;
	private volatile int initialModIconsLength = -1;                        // captured on client thread before first fetch
	private final AtomicBoolean started = new AtomicBoolean(false);
	private volatile ScheduledFuture<?> refreshTask = null;

	@Inject
	public TeamIconService(
		Client client,
		FauxBingoConfig config,
		@Named(FauxBingoPlugin.API_BASE_URL_KEY) Provider<String> apiBaseUrl,
		OkHttpClient okHttpClient,
		Gson gson,
		ScheduledExecutorService executor,
		ClientThread clientThread
	)
	{
		this.client = client;
		this.config = config;
		this.apiBaseUrl = apiBaseUrl;
		this.okHttpClient = okHttpClient;
		this.gson = gson;
		this.executor = executor;
		this.clientThread = clientThread;
	}

	public void start()
	{
		// Claimed here rather than by checking refreshTask, which stays null until the lambda below
		// reaches the client thread: two start() calls in quick succession - onConfigChanged lands
		// one on every apiToken/apiBaseUrl/enableBingoApi edit - would otherwise both schedule a
		// task, and only the second could ever be cancelled.
		if (!started.compareAndSet(false, true))
		{
			return;
		}

		// BooleanSupplier overload: returning false re-runs this next tick. Plugins start before the
		// game loads, so getModIcons() is null at the login screen and we have to wait for it.
		clientThread.invokeLater(() -> {
			if (!started.get())
			{
				// shutdown() ran before this reached the client thread.
				return true;
			}

			IndexedSprite[] modIcons = client.getModIcons();
			if (modIcons == null)
			{
				return false;
			}

			initialModIconsLength = modIcons.length;
			refreshTask = executor.scheduleAtFixedRate(this::fetchTeamData, 0, 5, TimeUnit.MINUTES);
			return true;
		});
	}

	private void fetchTeamData()
	{
		if (!enabled())
		{
			return;
		}

		try
		{
			Request request = new Request.Builder()
				.url(apiBaseUrl.get() + TEAMS_PATH)
				.header("Authorization", ApiConfigSanitizer.bearer(config.apiToken()))
				.build();

			TeamsResponseDto parsed;
			try (Response response = okHttpClient.newCall(request).execute())
			{
				if (!response.isSuccessful() || response.body() == null)
				{
					// Warn, not debug: an unusable roster silently disables every chat icon, and
					// the sibling services already warn on the same 401 (MeService, PresenceService).
					if (response.code() == 401)
					{
						log.warn("GET /v1/teams returned 401, token is missing or unknown. Team chat icons stay off until it is fixed.");
					}
					else
					{
						log.warn("GET /v1/teams returned {}: {}", response.code(), response.message());
					}
					return;
				}
				parsed = gson.fromJson(response.body().charStream(), TeamsResponseDto.class);
			}

			if (parsed == null || parsed.getTeams() == null)
			{
				return;
			}

			updateRsnMap(parsed.getTeams());
			updateChatCodeMap(parsed.getTeams());
			updateIcons(parsed.getTeams());
		}
		catch (Exception e)
		{
			log.debug("Error fetching team data", e);
		}
	}

	private void updateRsnMap(List<TeamRosterDto> teams)
	{
		synchronized (rsnToTeamId)
		{
			rsnToTeamId.clear();
			for (TeamRosterDto team : teams)
			{
				if (team.getId() == null || team.getPlayers() == null)
				{
					continue;
				}
				for (TeamPlayerDto player : team.getPlayers())
				{
					if (player.getAccounts() == null)
					{
						continue;
					}
					for (TeamAccountDto account : player.getAccounts())
					{
						if (account.getDisplayName() == null)
						{
							continue;
						}
						// Text.standardize, not trim+toLowerCase: the game encodes spaces in chat
						// names as \u00A0, so an RSN like "DH Herc" arrives as "dh\u00a0herc" and
						// would never match the API's plain space. Both sides must normalize the
						// same way or multi-word RSNs are unmatchable.
						String rsn = Text.standardize(account.getDisplayName());
						if (rsn.isEmpty())
						{
							continue;
						}
						rsnToTeamId.put(rsn, team.getId());
					}
				}
			}
		}
	}

	private void updateChatCodeMap(List<TeamRosterDto> teams)
	{
		synchronized (chatCodeToTeamId)
		{
			chatCodeToTeamId.clear();
			for (TeamRosterDto team : teams)
			{
				if (team.getId() == null)
				{
					continue;
				}
				// Trim here rather than in normalizeChatCode: whitespace around a stored code is
				// the server being untidy, but ": fork :" typed in chat is not a shortcode.
				String code = normalizeChatCode(team.getChatCode() == null ? null : team.getChatCode().trim());
				if (code == null)
				{
					continue;
				}
				// Codes are unique per event server-side, so a collision here means the website
				// let one through. First team in the response wins.
				if (chatCodeToTeamId.putIfAbsent(code, team.getId()) != null)
				{
					log.warn("Ignoring duplicate team chat code '{}' on team {}", code, team.getId());
				}
			}
		}
	}

	/**
	 * Both the roster and the text scanned out of chat go through this, so the two can never
	 * disagree about what counts as a code.
	 *
	 * The letter requirement is what keeps timestamps safe: without it a team whose code was "30"
	 * would turn the {@code :30:} inside "10:30:45" into an icon.
	 *
	 * @return the normalized code, or null if this is not a usable shortcode
	 */
	private static String normalizeChatCode(String raw)
	{
		if (raw == null || raw.isEmpty() || raw.length() > MAX_CHAT_CODE_LENGTH)
		{
			return null;
		}

		boolean hasLetter = false;
		for (int i = 0; i < raw.length(); i++)
		{
			char c = Character.toLowerCase(raw.charAt(i));
			if (c >= 'a' && c <= 'z')
			{
				hasLetter = true;
			}
			else if (!((c >= '0' && c <= '9') || c == '_'))
			{
				return null;
			}
		}

		return hasLetter ? raw.toLowerCase(Locale.ROOT) : null;
	}

	/**
	 * @return the mod icon index for this code's team, or null if the code is unknown or that
	 * team's icon has not downloaded yet - callers leave the literal ":fork:" in place
	 */
	private Integer spriteIndexForCode(String rawCode)
	{
		String code = normalizeChatCode(rawCode);
		if (code == null)
		{
			return null;
		}

		String teamId;
		synchronized (chatCodeToTeamId)
		{
			teamId = chatCodeToTeamId.get(code);
		}

		if (teamId == null)
		{
			return null;
		}

		synchronized (teamToSpriteIndex)
		{
			return teamToSpriteIndex.get(teamId);
		}
	}

	/**
	 * Replaces every {@code :code:} that resolves to a registered team icon with its {@code <img>}
	 * tag, scanning left to right.
	 *
	 * @return the rewritten message, or null if nothing matched
	 */
	String updateMessage(String message)
	{
		if (message == null || message.length() < 3)
		{
			return null;
		}

		StringBuilder out = null;
		int copied = 0;
		int replacements = 0;
		int search = 0;

		while (replacements < MAX_REPLACEMENTS_PER_MESSAGE)
		{
			int open = message.indexOf(':', search);
			if (open < 0)
			{
				break;
			}

			int close = message.indexOf(':', open + 1);
			if (close < 0)
			{
				break;
			}

			Integer index = close - open - 1 > MAX_CHAT_CODE_LENGTH
				? null
				: spriteIndexForCode(message.substring(open + 1, close));

			if (index == null)
			{
				// Resume from the closing colon rather than past it: in ":x:fork:" the colon that
				// ended the non-match is the one that opens ":fork:".
				search = close;
				continue;
			}

			if (out == null)
			{
				out = new StringBuilder(message.length());
			}
			out.append(message, copied, open).append("<img=").append(index).append('>');
			copied = close + 1;
			search = close + 1;
			replacements++;
		}

		if (out == null)
		{
			return null;
		}

		return out.append(message, copied, message.length()).toString();
	}

	/**
	 * The player-authored channels, matching RuneLite's own Emojis plugin. Game and system
	 * messages are excluded so Jagex-worded lines containing a colon pair cannot be rewritten.
	 */
	private static boolean isPlayerChat(ChatMessageType type)
	{
		switch (type)
		{
			case PUBLICCHAT:
			case MODCHAT:
			case FRIENDSCHAT:
			case CLAN_CHAT:
			case CLAN_GUEST_CHAT:
			case CLAN_GIM_CHAT:
			case PRIVATECHAT:
			case PRIVATECHATOUT:
			case MODPRIVATECHAT:
				return true;
			default:
				return false;
		}
	}

	private void updateIcons(List<TeamRosterDto> teams)
	{
		for (TeamRosterDto team : teams)
		{
			String teamId = team.getId();

			if (teamId == null || teamId.trim().isEmpty())
			{
				continue;
			}

			// A team whose sprite is already registered is done for this session - the icon URL is
			// derived from the team id, so it never changes.
			synchronized (teamToSpriteIndex)
			{
				if (teamToSpriteIndex.containsKey(teamId))
				{
					continue;
				}
			}
			// A failure is remembered for a cooldown rather than the whole session: an icon that
			// 404'd because it had not been uploaded yet, or a download that hit a network blip,
			// has to be able to recover without the user restarting the client.
			synchronized (iconFetchFailures)
			{
				Long failedAt = iconFetchFailures.get(teamId);
				if (failedAt != null && System.currentTimeMillis() - failedAt < ICON_RETRY_COOLDOWN_MS)
				{
					continue;
				}
			}

			downloadAndRegisterIcon(teamId);
		}
	}

	/**
	 * Builds {apiBaseUrl}/v1/teams/{teamId}/icon. The team id is added as an encoded path segment so
	 * a server-supplied id cannot inject extra segments, and the result is rejected unless it is
	 * still under the hardcoded /v1/teams path.
	 */
	private HttpUrl iconUrl(String teamId)
	{
		HttpUrl base = HttpUrl.parse(apiBaseUrl.get());
		if (base == null)
		{
			return null;
		}

		HttpUrl teamsUrl = base.newBuilder()
			.addPathSegment("v1")
			.addPathSegment("teams")
			.build();

		HttpUrl url = teamsUrl.newBuilder()
			.addPathSegment(teamId)
			.addPathSegment(ICON_SEGMENT)
			.build();

		if (!url.encodedPath().startsWith(teamsUrl.encodedPath() + "/"))
		{
			log.debug("Refusing icon URL for team id {}: escapes {}", teamId, teamsUrl.encodedPath());
			return null;
		}

		return url;
	}

	private void downloadAndRegisterIcon(String teamId)
	{
		HttpUrl url = iconUrl(teamId);
		if (url == null)
		{
			rememberIconFailure(teamId);
			return;
		}

		// RuneLite's injected OkHttpClient carries a shared on-disk cache, and the icon route
		// answers with `Cache-Control: public, max-age=3600` and no validator - so without this an
		// icon replaced on the site stays stale for an hour, across plugin toggles and client
		// restarts alike. This runs once per team per session, so always going to the network is
		// cheap.
		Request request = new Request.Builder()
			.url(url)
			.cacheControl(CacheControl.FORCE_NETWORK)
			.header("Authorization", ApiConfigSanitizer.bearer(config.apiToken()))
			.build();

		try (Response response = okHttpClient.newCall(request).execute())
		{
			if (!response.isSuccessful() || response.body() == null)
			{
				log.debug("Failed to download icon for team {}: {}", teamId, response);
				rememberIconFailure(teamId);
				return;
			}

			// A redirect would send us to a host the server picked rather than one derived from the
			// configured API base, so only accept a body that came back from the URL we asked for.
			if (!url.equals(response.request().url()))
			{
				log.debug("Ignoring redirected icon response for team {}: {}", teamId, response.request().url());
				rememberIconFailure(teamId);
				return;
			}

			BufferedImage image = ImageIO.read(response.body().byteStream());
			if (image == null)
			{
				log.debug("Failed to decode icon for team {}", teamId);
				rememberIconFailure(teamId);
				return;
			}

			BufferedImage resized = ImageUtil.resizeImage(image, 18, 16);
			clientThread.invokeLater(() -> {
				IndexedSprite sprite = ImageUtil.getImageIndexedSprite(resized, client);
				IndexedSprite[] current = client.getModIcons();
				IndexedSprite[] updated = Arrays.copyOf(current, current.length + 1);
				updated[current.length] = sprite;
				client.setModIcons(updated);
				iconsRegisteredCount++;

				synchronized (teamToSpriteIndex)
				{
					teamToSpriteIndex.put(teamId, current.length);
				}
			});
		}
		catch (Exception e)
		{
			log.debug("Error registering icon for team " + teamId, e);
			rememberIconFailure(teamId);
		}
	}

	private void rememberIconFailure(String teamId)
	{
		synchronized (iconFetchFailures)
		{
			iconFetchFailures.put(teamId, System.currentTimeMillis());
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (!enabled() || !config.showTeamIconsInChat())
		{
			return;
		}

		MessageNode node = event.getMessageNode();
		if (node == null)
		{
			return;
		}

		boolean changed = badgeSenderName(event, node);
		changed |= replaceChatCodes(event, node);

		if (changed)
		{
			// The chatbox line for this message may already be built, and nothing rebuilds it on
			// its own - without this the edit does not show until some later message forces a
			// rebuild.
			client.refreshChat();
		}
	}

	private boolean badgeSenderName(ChatMessage event, MessageNode node)
	{
		String name = event.getName();
		if (name == null)
		{
			return false;
		}

		String sanitizedName = Text.standardize(name);
		String teamId;
		synchronized (rsnToTeamId)
		{
			teamId = rsnToTeamId.get(sanitizedName);
		}

		if (teamId == null)
		{
			return false;
		}

		Integer index;
		synchronized (teamToSpriteIndex)
		{
			index = teamToSpriteIndex.get(teamId);
		}

		if (index == null)
		{
			return false;
		}

		node.setName("<img=" + index + ">" + name);
		return true;
	}

	private boolean replaceChatCodes(ChatMessage event, MessageNode node)
	{
		if (event.getType() == null || !isPlayerChat(event.getType()))
		{
			return false;
		}

		String updated = updateMessage(node.getValue());
		if (updated == null)
		{
			return false;
		}

		// setValue, not setRuneLiteFormatMessage: RuneLite's own Emojis plugin edits the same
		// field, so both plugins' replacements survive whichever order the two handlers run in.
		node.setValue(updated);
		return true;
	}

	@Subscribe
	public void onOverheadTextChanged(OverheadTextChanged event)
	{
		if (!enabled() || !config.showTeamIconsInChat())
		{
			return;
		}

		Actor actor = event.getActor();
		if (!(actor instanceof Player))
		{
			return;
		}

		String updated = updateMessage(event.getOverheadText());
		if (updated == null)
		{
			return;
		}

		actor.setOverheadText(updated);
	}

	public void shutdown()
	{
		started.set(false);

		if (refreshTask != null)
		{
			refreshTask.cancel(false);
			refreshTask = null;
		}

		clientThread.invokeLater(() -> {
			if (initialModIconsLength >= 0)
			{
				int expectedLength = initialModIconsLength + iconsRegisteredCount;
				if (client.getModIcons().length == expectedLength)
				{
					// No other plugin has appended after us — safe to truncate.
					client.setModIcons(Arrays.copyOf(client.getModIcons(), initialModIconsLength));
				}
				else
				{
					// Another plugin has appended sprites after ours. Truncating would corrupt
					// their indices. Leave the array intact and accept that our sprites are leaked
					// for the remainder of this session.
					log.debug("Skipping modIcons truncation: array length {} does not match expected {}. " +
							"Another plugin has appended sprites after TeamIconService.",
						client.getModIcons().length, expectedLength);
				}
			}
		});

		iconsRegisteredCount = 0;
		initialModIconsLength = -1;

		synchronized (rsnToTeamId)
		{
			rsnToTeamId.clear();
		}
		synchronized (chatCodeToTeamId)
		{
			chatCodeToTeamId.clear();
		}
		synchronized (teamToSpriteIndex)
		{
			teamToSpriteIndex.clear();
		}
		synchronized (iconFetchFailures)
		{
			iconFetchFailures.clear();
		}
	}

	private boolean enabled()
	{
		return config.enableBingoApi() && !ApiConfigSanitizer.sanitize(config.apiToken()).isEmpty()
			&& !apiBaseUrl.get().isEmpty();
	}
}

package com.fauxbingo.services;

import com.fauxbingo.FauxBingoConfig;
import com.google.gson.Gson;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

import java.io.IOException;

/**
 * Service for interacting with the WiseOldMan API.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class WiseOldManService
{
	private static final String WOM_API_HOST = "api.wiseoldman.net";
	private static final String WOM_API_VERSION = "v2";
	private static final String USER_AGENT = "FauxBingo-RuneLite-Plugin";

	private final Client client;
	private final FauxBingoConfig config;
	private final OkHttpClient okHttpClient;
	private final Gson gson;

	public void updatePlayer(String username)
	{
		if (!config.enableWomAutoUpdate())
		{
			return;
		}

		if (username == null || username.isEmpty())
		{
			log.warn("Cannot update WiseOldMan: username is null or empty");
			return;
		}

		long accountHash = client.getAccountHash();

		// Build the API URL: POST /v2/players/{username}
		HttpUrl url = new HttpUrl.Builder()
			.scheme("https")
			.host(WOM_API_HOST)
			.addPathSegment(WOM_API_VERSION)
			.addPathSegment("players")
			.addPathSegment(username)
			.build();

		// Create payload with account hash for verification
		WomPlayerUpdate payload = new WomPlayerUpdate(accountHash);
		String json = gson.toJson(payload);

		RequestBody body = RequestBody.create(
			MediaType.parse("application/json; charset=utf-8"),
			json
		);

		Request request = new Request.Builder()
			.url(url)
			.header("User-Agent", USER_AGENT)
			.post(body)
			.build();

		// Send the request asynchronously
		okHttpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Failed to update WiseOldMan stats for {}: {}", username, e.getMessage());
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException
			{
				try
				{
					if (response.isSuccessful())
					{
						log.info("Successfully updated WiseOldMan stats for {}", username);
					}
					else
					{
						log.debug("WiseOldMan update returned status {}: {}", 
							response.code(), response.message());
					}
				}
				finally
				{
					response.close();
				}
			}
		});
	}

	private static class WomPlayerUpdate
	{
		private final long accountHash;

		public WomPlayerUpdate(long accountHash)
		{
			this.accountHash = accountHash;
		}
	}
}

