	/**
	 * Regression test for the double-report bug: the reward interface reloading for the *same*
	 * chest (e.g. the player finally interacting with it long after the loot screen first
	 * populated) must not re-arm the latch. Only a real instance boundary may do that.
	 */
	@Test
	public void testWidgetReloadWithoutInstanceChangeDoesNotDoubleReport()
	{
		ChatMessage kcEvent = new ChatMessage();
		kcEvent.setType(ChatMessageType.GAMEMESSAGE);
		kcEvent.setMessage("Your completed Chambers of Xeric count is: 100.");
		raidLootHandler.onChatMessage(kcEvent);

		when(itemContainer.getItems()).thenReturn(new Item[]{new Item(20997, 1)});
		when(itemManager.getItemComposition(20997)).thenReturn(itemComposition);
		when(itemComposition.getName()).thenReturn("Twisted bow");

		ItemContainerChanged containerEvent = new ItemContainerChanged(581, itemContainer);
		raidLootHandler.onItemContainerChanged(containerEvent);

		// Player is still standing in the same instance, but the reward interface reloads (e.g.
		// they finally click through it). isInInstancedRegion() hasn't changed, so this must be a
		// no-op for the latch.
		when(client.isInInstancedRegion()).thenReturn(false);
		GameStateChanged reload = new GameStateChanged();
		reload.setGameState(GameState.LOADING);
		raidLootHandler.onGameStateChanged(reload);

		// The same, unchanged container reports again.
		raidLootHandler.onItemContainerChanged(containerEvent);

		verify(dropCorrelationService, times(1)).report(any());
	}

	/** A genuine instance boundary must still re-arm the latch for the next raid's loot. */
	@Test
	public void testNewRaidAfterLeavingInstanceIsReportedAgain()
	{
		when(itemContainer.getItems()).thenReturn(new Item[]{new Item(20997, 1)});
		when(itemManager.getItemComposition(20997)).thenReturn(itemComposition);
		when(itemComposition.getName()).thenReturn("Twisted bow");

		// Enter the raid instance.
		when(client.isInInstancedRegion()).thenReturn(true);
		GameStateChanged enter = new GameStateChanged();
		enter.setGameState(GameState.LOADING);
		raidLootHandler.onGameStateChanged(enter);

		ItemContainerChanged containerEvent = new ItemContainerChanged(581, itemContainer);
		raidLootHandler.onItemContainerChanged(containerEvent);

		// Leave the instance after collecting loot.
		when(client.isInInstancedRegion()).thenReturn(false);
		GameStateChanged leave = new GameStateChanged();
		leave.setGameState(GameState.LOADING);
		raidLootHandler.onGameStateChanged(leave);

		// Enter a second raid instance and get a fresh chest.
		when(client.isInInstancedRegion()).thenReturn(true);
		GameStateChanged enterAgain = new GameStateChanged();
		enterAgain.setGameState(GameState.LOADING);
		raidLootHandler.onGameStateChanged(enterAgain);

		raidLootHandler.onItemContainerChanged(containerEvent);

		verify(dropCorrelationService, times(2)).report(any());
	}

	private void tickWithInRaidVarbit(int value)
	{
		when(client.getVarbitValue(VarbitID.RAIDS_CLIENT_INDUNGEON)).thenReturn(value);
		raidLootHandler.onGameTick(new GameTick());
	}

	/** Chat lands when Olm dies, the chest can be opened much later: hold until they leave. */
	@Test
	public void testCorrelationHeldForAsLongAsThePlayerIsInChambers()
	{
		tickWithInRaidVarbit(1);
		tickWithInRaidVarbit(1);
		verify(dropCorrelationService).holdNewGroups();
		verify(dropCorrelationService, never()).releaseHeldGroups();

		tickWithInRaidVarbit(0);
		verify(dropCorrelationService).releaseHeldGroups();
	}

	@Test
	public void testLoggingOutOfChambersReleasesTheHold()
	{
		tickWithInRaidVarbit(1);

		GameStateChanged logout = new GameStateChanged();
		logout.setGameState(GameState.LOGIN_SCREEN);
		raidLootHandler.onGameStateChanged(logout);

		verify(dropCorrelationService).releaseHeldGroups();
	}

	/** Ticks outside the raid leave the hold alone. */
	@Test
	public void testTicksOutsideChambersDoNotTouchTheHold()
	{
		tickWithInRaidVarbit(0);
		tickWithInRaidVarbit(0);

		verify(dropCorrelationService, never()).holdNewGroups();
		verify(dropCorrelationService, never()).releaseHeldGroups();
	}
}

package com.fauxbingo.handlers;

import com.fauxbingo.services.DropCorrelationService;
import com.fauxbingo.services.ScreenshotService;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.events.ServerNpcLoot;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

/**
 * Yama and The Whisperer drop loot away from their own tile, so LootManager finds nothing to scan
 * and never posts NpcLootReceived. ServerNpcLoot is the only event they produce. Ordinary NPCs fire
 * both, so these also pin down the pairing that stops a double post.
 */
@RunWith(MockitoJUnitRunner.Silent.class)
public class ServerNpcLootHandlerTest
{
	private static final int OATHPLATE_SHARDS_ID = 30765;
	private static final long SHARD_PRICE = 183_000L;
	private static final int BONES_ID = 526;
	private static final int CHAOS_RUNE_ID = 562;
	private static final int COINS_ID = 995;
	private static final int BIG_BONES_ID = 532;
	private static final int RAW_RAT_MEAT_ID = 2134;
	private static final int SCURRIUS_SPINE_ID = 28798;
	private static final int SCROLL_BOX_MEDIUM_ID = 24362;

	@Mock
	private ItemManager itemManager;
	@Mock
	private ScreenshotService screenshotService;
	@Mock
	private ScheduledExecutorService executor;
	@Mock
	private DropCorrelationService dropCorrelationService;
	@Mock
	private NPC npc;
	@Mock
	private NPCComposition npcComposition;
	@Mock
	private Client client;

	private LootEventHandler lootEventHandler;

	@Before
	public void before()
	{
		lootEventHandler = new LootEventHandler(itemManager, screenshotService, executor, dropCorrelationService, client);

		doAnswer(inv -> {
			((Runnable) inv.getArgument(0)).run();
			return null;
		}).when(executor).execute(any());

		doAnswer(inv -> {
			java.util.function.Consumer<java.awt.image.BufferedImage> cb = inv.getArgument(0);
			cb.accept(new java.awt.image.BufferedImage(1, 1, java.awt.image.BufferedImage.TYPE_INT_RGB));
			return null;
		}).when(screenshotService).requestScreenshot(any());

		ItemComposition shards = mock(ItemComposition.class);
		when(shards.getName()).thenReturn("Oathplate shards");
		when(itemManager.getItemComposition(OATHPLATE_SHARDS_ID)).thenReturn(shards);
		when(itemManager.getItemPrice(OATHPLATE_SHARDS_ID)).thenReturn(SHARD_PRICE);

		ItemComposition bones = mock(ItemComposition.class);
		when(bones.getName()).thenReturn("Bones");
		when(itemManager.getItemComposition(BONES_ID)).thenReturn(bones);
		when(itemManager.getItemPrice(BONES_ID)).thenReturn(100L);

		ItemComposition chaos = mock(ItemComposition.class);
		when(chaos.getName()).thenReturn("Chaos rune");
		when(itemManager.getItemComposition(CHAOS_RUNE_ID)).thenReturn(chaos);

		named(COINS_ID, "Coins");
		named(BIG_BONES_ID, "Big bones");
		named(RAW_RAT_MEAT_ID, "Raw rat meat");
		named(SCURRIUS_SPINE_ID, "Scurrius' spine");
		named(SCROLL_BOX_MEDIUM_ID, "Scroll box (medium)");
	}

	private void named(int itemId, String name)
	{
		ItemComposition composition = mock(ItemComposition.class);
		when(composition.getName()).thenReturn(name);
		when(itemManager.getItemComposition(itemId)).thenReturn(composition);
	}

	private ServerNpcLoot serverLoot(String name, List<ItemStack> items)
	{
		when(npcComposition.getName()).thenReturn(name);
		return new ServerNpcLoot(npcComposition, items);
	}

	private NpcLootReceived tileLoot(String name, List<ItemStack> items)
	{
		when(npc.getName()).thenReturn(name);
		return new NpcLootReceived(npc, items);
	}

	private static List<ItemStack> shards()
	{
		return Collections.singletonList(new ItemStack(OATHPLATE_SHARDS_ID, 12, null));
	}

	/** The reported bug: Yama produces no NpcLootReceived, so this is the only signal for the kill. */
	@Test
	public void yamaShardsFireOnServerEventAlone()
	{
		lootEventHandler.onServerNpcLoot(serverLoot("Yama", shards()));

		verify(dropCorrelationService).report(any());
	}

	@Test
	public void whispererLootFiresOnServerEventAlone()
	{
		lootEventHandler.onServerNpcLoot(serverLoot("The Whisperer", shards()));

		verify(dropCorrelationService).report(any());
	}

	/** Ordinary NPC: both events arrive for one kill and only one report comes out. */
	@Test
	public void bothEventsForOneKillReportOnce()
	{
		lootEventHandler.onServerNpcLoot(serverLoot("Vorkath", shards()));
		lootEventHandler.onNpcLootReceived(tileLoot("Vorkath", shards()));

		verify(dropCorrelationService, times(1)).report(any());
	}

	/** Order should not matter, the tile scan can land first. */
	@Test
	public void pairingWorksInEitherOrder()
	{
		lootEventHandler.onNpcLootReceived(tileLoot("Vorkath", shards()));
		lootEventHandler.onServerNpcLoot(serverLoot("Vorkath", shards()));

		verify(dropCorrelationService, times(1)).report(any());
	}

	/** Pairing consumes one entry, so identical repeat kills are not swallowed. */
	@Test
	public void twoIdenticalKillsBothReport()
	{
		List<ItemStack> loot = Collections.singletonList(new ItemStack(BONES_ID, 1, null));

		lootEventHandler.onServerNpcLoot(serverLoot("Goblin", loot));
		lootEventHandler.onNpcLootReceived(tileLoot("Goblin", loot));
		lootEventHandler.onServerNpcLoot(serverLoot("Goblin", loot));
		lootEventHandler.onNpcLootReceived(tileLoot("Goblin", loot));

		verify(dropCorrelationService, times(2)).report(any());
	}

	/** Interleaved, which is what a delayed tile scan looks like against a fast second kill. */
	@Test
	public void interleavedIdenticalKillsBothReport()
	{
		List<ItemStack> loot = Collections.singletonList(new ItemStack(BONES_ID, 1, null));

		lootEventHandler.onServerNpcLoot(serverLoot("Goblin", loot));
		lootEventHandler.onServerNpcLoot(serverLoot("Goblin", loot));
		lootEventHandler.onNpcLootReceived(tileLoot("Goblin", loot));
		lootEventHandler.onNpcLootReceived(tileLoot("Goblin", loot));

		verify(dropCorrelationService, times(2)).report(any());
	}

	/** Two of the same event in a row are never each other's pair. */
	@Test
	public void repeatedServerEventsAreNotPairedTogether()
	{
		lootEventHandler.onServerNpcLoot(serverLoot("Yama", shards()));
		lootEventHandler.onServerNpcLoot(serverLoot("Yama", shards()));

		verify(dropCorrelationService, times(2)).report(any());
	}

	/** Different loot from the same NPC is a different kill, not a pair. */
	@Test
	public void differentLootIsNotPaired()
	{
		lootEventHandler.onServerNpcLoot(serverLoot("Vorkath", shards()));
		lootEventHandler.onNpcLootReceived(tileLoot("Vorkath", Collections.singletonList(new ItemStack(BONES_ID, 1, null))));

		verify(dropCorrelationService, times(2)).report(any());
	}

	/** Item ordering differs between the two events, the key must not care. */
	@Test
	public void itemOrderDoesNotBreakPairing()
	{
		ItemStack shard = new ItemStack(OATHPLATE_SHARDS_ID, 12, null);
		ItemStack bone = new ItemStack(BONES_ID, 1, null);

		lootEventHandler.onServerNpcLoot(serverLoot("Yama", Arrays.asList(shard, bone)));
		lootEventHandler.onNpcLootReceived(tileLoot("Yama", Arrays.asList(bone, shard)));

		verify(dropCorrelationService, times(1)).report(any());
	}

	/**
	 * Mithril dragon: the three unnoted bars come through as separate 1x stacks from one event and
	 * a single 3x stack from the other. Still one kill, so still one report.
	 */
	@Test
	public void differentStackingOfNonStackablesStillPairs()
	{
		ItemStack bone = new ItemStack(BONES_ID, 1, null);

		lootEventHandler.onNpcLootReceived(tileLoot("Mithril dragon", Arrays.asList(
			bone,
			new ItemStack(OATHPLATE_SHARDS_ID, 1, null),
			new ItemStack(OATHPLATE_SHARDS_ID, 1, null),
			new ItemStack(OATHPLATE_SHARDS_ID, 1, null))));
		lootEventHandler.onServerNpcLoot(serverLoot("Mithril dragon", Arrays.asList(
			bone,
			new ItemStack(OATHPLATE_SHARDS_ID, 3, null))));

		verify(dropCorrelationService, times(1)).report(any());
	}

	/**
	 * Bonecrusher: the Dragon bones never reach the ground, so the tile scan is short an item the
	 * server event still lists. Same kill, one report, whichever lands first.
	 */
	@Test
	public void tileScanMissingAnAutoCollectedItemStillPairs()
	{
		ItemStack bone = new ItemStack(BONES_ID, 1, null);
		List<ItemStack> ground = Arrays.asList(
			new ItemStack(OATHPLATE_SHARDS_ID, 1, null),
			new ItemStack(OATHPLATE_SHARDS_ID, 1, null),
			new ItemStack(OATHPLATE_SHARDS_ID, 1, null));
		List<ItemStack> server = Arrays.asList(bone, new ItemStack(OATHPLATE_SHARDS_ID, 3, null));

		lootEventHandler.onServerNpcLoot(serverLoot("Mithril dragon", server));
		lootEventHandler.onNpcLootReceived(tileLoot("Mithril dragon", ground));
		lootEventHandler.onNpcLootReceived(tileLoot("Mithril dragon", ground));
		lootEventHandler.onServerNpcLoot(serverLoot("Mithril dragon", server));

		verify(dropCorrelationService, times(2)).report(any());
	}

	/** Each side holding something the other lacks is two different kills, not one partial one. */
	@Test
	public void lootThatOverlapsWithoutContainmentIsNotPaired()
	{
		ItemStack bone = new ItemStack(BONES_ID, 1, null);
		ItemStack shard = new ItemStack(OATHPLATE_SHARDS_ID, 12, null);

		lootEventHandler.onServerNpcLoot(serverLoot("Vorkath", Arrays.asList(bone, shard)));
		lootEventHandler.onNpcLootReceived(tileLoot("Vorkath", Arrays.asList(bone, new ItemStack(CHAOS_RUNE_ID, 24, null))));

		verify(dropCorrelationService, times(2)).report(any());
	}

	/**
	 * The reported Scurrius double: one list had the Big bones but not the Scroll box (medium), the
	 * other the reverse. Both differences are items the events are known to disagree on, so this is
	 * one kill, whichever side each list came from.
	 */
	@Test
	public void listsDifferingOnlyInBonesAndClueBoxPair()
	{
		List<ItemStack> withBones = Arrays.asList(
			new ItemStack(COINS_ID, 5000, null),
			new ItemStack(BIG_BONES_ID, 1, null),
			new ItemStack(RAW_RAT_MEAT_ID, 5, null),
			new ItemStack(SCURRIUS_SPINE_ID, 1, null));
		List<ItemStack> withScrollBox = Arrays.asList(
			new ItemStack(COINS_ID, 5000, null),
			new ItemStack(RAW_RAT_MEAT_ID, 5, null),
			new ItemStack(SCURRIUS_SPINE_ID, 1, null),
			new ItemStack(SCROLL_BOX_MEDIUM_ID, 1, null));

		lootEventHandler.onServerNpcLoot(serverLoot("Scurrius", withBones));
		lootEventHandler.onNpcLootReceived(tileLoot("Scurrius", withScrollBox));
		lootEventHandler.onNpcLootReceived(tileLoot("Scurrius", withBones));
		lootEventHandler.onServerNpcLoot(serverLoot("Scurrius", withScrollBox));

		verify(dropCorrelationService, times(2)).report(any());
	}

	/** A one-sided difference doesn't excuse a real one alongside it. */
	@Test
	public void oneSidedDifferenceAlongsideARealOneIsNotPaired()
	{
		lootEventHandler.onServerNpcLoot(serverLoot("Scurrius", Arrays.asList(
			new ItemStack(COINS_ID, 5000, null),
			new ItemStack(BIG_BONES_ID, 1, null),
			new ItemStack(SCURRIUS_SPINE_ID, 1, null))));
		lootEventHandler.onNpcLootReceived(tileLoot("Scurrius", Arrays.asList(
			new ItemStack(COINS_ID, 5000, null),
			new ItemStack(RAW_RAT_MEAT_ID, 5, null),
			new ItemStack(SCROLL_BOX_MEDIUM_ID, 1, null))));

		verify(dropCorrelationService, times(2)).report(any());
	}

	/** An exact match queued behind a subset match gets the pair, leaving the subset for its own kill. */
	@Test
	public void exactMatchIsPreferredOverAnEarlierSubset()
	{
		List<ItemStack> bonesOnly = Collections.singletonList(new ItemStack(BONES_ID, 1, null));
		List<ItemStack> bonesAndShards = Arrays.asList(new ItemStack(BONES_ID, 1, null), new ItemStack(OATHPLATE_SHARDS_ID, 12, null));

		lootEventHandler.onServerNpcLoot(serverLoot("Vorkath", bonesAndShards));
		lootEventHandler.onServerNpcLoot(serverLoot("Vorkath", bonesOnly));
		lootEventHandler.onNpcLootReceived(tileLoot("Vorkath", bonesOnly));
		lootEventHandler.onNpcLootReceived(tileLoot("Vorkath", bonesAndShards));

		verify(dropCorrelationService, times(2)).report(any());
	}

	@Test
	public void nullCompositionAndEmptyItemsAreSafe()
	{
		lootEventHandler.onServerNpcLoot(new ServerNpcLoot(null, shards()));
		lootEventHandler.onServerNpcLoot(serverLoot("Yama", Collections.emptyList()));

		verify(dropCorrelationService, times(1)).report(any());
	}
}

